  const processLink = (linkPath: string): string => {
    // Skip external URLs
    if (linkPath.startsWith("http://") || linkPath.startsWith("https://")) {
      return linkPath;
    }

    // Separate file path from heading/block fragment (e.g. "Note.md#section" → filePath="Note.md", fragment="#section")
    // so that file resolution operates only on the file path portion.
    const hashIndex = linkPath.indexOf("#");
    const filePath = hashIndex !== -1 ? linkPath.slice(0, hashIndex) : linkPath;
    const fragment = hashIndex !== -1 ? linkPath.slice(hashIndex) : "";

    const resolveFilePath = (path: string): string => {
      // First, try to find if this link resolves to one of our imported assets
      const importedAssetFile = findImportedAssetFile(path);
      if (importedAssetFile) {
        return getRelativeLinkPath(importedAssetFile.path);
      }

      const newPath = getNewPathForLink(path);
      if (newPath) return getRelativeLinkPath(newPath);

      // Only resolve to files under import/{spaceName}/ so we don't point at the wrong vault's files
      const resolvedFile = app.metadataCache.getFirstLinkpathDest(
        path,
        targetFile.path,
      );
      const isInImportFolder =
        importFolder &&
        resolvedFile &&
        resolvedFile.path.startsWith(importFolder + "/");
      if (isInImportFolder && resolvedFile) {
        return getRelativeLinkPath(resolvedFile.path);
      }

      // Unresolved (dead) link from another vault: rewrite so that when the user creates the file from this link, it is created under import/{vaultName}/ in the same relative position as in the source vault
      if (importFolder && originalNodePath && !resolvedFile) {
        // Vault-relative link (e.g. "Discourse Nodes/EVD - no relation testing") -> use as-is. Path-from-current-file (e.g. "EVD - no relation testing") -> resolve relative to source note dir
        const canonicalSourcePath =
          path.includes("/") && !path.startsWith(".") && !path.startsWith("/")
            ? normalizePathForLookup(path)
            : (getCanonicalFromOriginalNote(path) ??
              normalizePathForLookup(path));
        return `${importFolder}/${canonicalSourcePath}`;
      }

      return path;
    };

    return resolveFilePath(filePath) + fragment;
  };

  // Match wiki links: [[path]] or [[path|alias]]
  const wikiLinkRegex = /\[\[([^\]]+)\]\]/g;
  updatedContent = updatedContent.replace(
    wikiLinkRegex,
    (match, linkContent: string) => {
      // Extract path and optional alias
      const [linkPath, alias] = linkContent
        .split("|")
        .map((s: string) => s.trim());
      if (!linkPath) return match;
      let processedPath = processLink(linkPath);
      const hashIdx = processedPath.indexOf("#");
      const pathBeforeHash =
        hashIdx !== -1 ? processedPath.slice(0, hashIdx) : processedPath;
      const pathAfterHash = hashIdx !== -1 ? processedPath.slice(hashIdx) : "";
      if (pathBeforeHash.endsWith(".md") && !linkPath.endsWith(".md")) {
        processedPath = pathBeforeHash.slice(0, -3) + pathAfterHash;
      }
      if (alias) {
        return `[[${processedPath}|${alias}]]`;
      }
      return `[[${processedPath}|${linkPath}]]`;
    },
  );

  // Match markdown links (non-image): [text](path) — internal paths resolved like wikilinks, href kept URL-encoded
  const markdownLinkRegex = /(?<!!)\[([^\]]*)\]\(([^)]+)\)/g;
  updatedContent = updatedContent.replace(
    markdownLinkRegex,
    (match, linkText: string, linkPath: string) => {
      if (!linkPath) return match;
      // Resolve by row before looking at the shape of the link: a Roam-origin asset is
      // referenced by its storage URL. Matched on the raw link, because the decoding
      // below would mangle the percent-escaping a storage URL carries.
      const mappedFromUrl = getNewPathForLink(linkPath);
      if (mappedFromUrl)
        return `[${linkText}](${encodePathForMarkdownLink(getRelativeLinkPath(mappedFromUrl))})`;
      linkPath = linkPath
        .split("/")
        .map((segment) => {
          try {
            return decodeURIComponent(segment);
          } catch {
            return segment;
          }
        })
        .join("/");
      // A URL with no mapping is genuinely external and is left exactly as written.
      if (linkPath.startsWith("http://") || linkPath.startsWith("https://")) {
        return match;
      }
      const processedPath = encodePathForMarkdownLink(processLink(linkPath));
      return `[${linkText}](${processedPath})`;
    },
  );

  // Match markdown image links: ![alt](path) or ![alt](path "title")
  const markdownImageRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
  updatedContent = updatedContent.replace(
    markdownImageRegex,
    (match, alt: string, linkPath: string) => {
      // Remove optional title from linkPath: "path" or "path title"
      const cleanPath = linkPath.replace(/\s+"[^"]*"$/, "").trim();

      const isExternalUrl =
        cleanPath.startsWith("http://") || cleanPath.startsWith("https://");
      // Resolve by row, not by link shape: a mapped URL is one we now hold locally, an
      // unmapped one is genuinely external and is left as written.
      if (isExternalUrl) {
        const mappedFromUrl = getNewPathForLink(cleanPath);
        if (!mappedFromUrl) return match;
        return `![${alt}](${encodePathForMarkdownLink(getRelativeLinkPath(mappedFromUrl))})`;
      }

      // First, try to find if this link resolves to one of our imported assets
      const importedAssetFile = findImportedAssetFile(cleanPath);
      if (importedAssetFile) {
        const linkText = encodePathForMarkdownLink(
          getRelativeLinkPath(importedAssetFile.path),
        );
        return `![${alt}](${linkText})`;
      }

      const newPath = getNewPathForLink(cleanPath);
      if (newPath)
        return `![${alt}](${encodePathForMarkdownLink(getRelativeLinkPath(newPath))})`;

      return match;
    },
  );

  return updatedContent;
};

/**
 * A variant of a colliding path, distinguished by the asset's own content hash:
 * `report.png` becomes `report-1a2b3c4d.png`.
 *
 * Keyed on the hash rather than a counter so the name is stable: a re-import has to land
import { FORMAT_PLACEHOLDER } from "@repo/database/lib/decorateTitle";
import getDiscourseNodes, { type DiscourseNode } from "./getDiscourseNodes";
import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";
import getDiscourseNodeFormatExpression from "./getDiscourseNodeFormatExpression";
import { extractFieldFromTitle } from "./extractContentFromTitle";
import { readImportedSourceIdentity } from "./importedSourceIdentity";

// Temporary hack, until slots are a first-class node type setting: a node type whose
// format has a {source} placeholder (Evidence, among the default node types) is taken
// to have a sourceDocument slot, filled by the Source node named in a node's title.
// Both the sync and the publish path express this, so it lives here rather than in
// either of them.

export const SOURCE_SLOT = "sourceDocument";
export const MISSING_SOURCE_PLACEHOLDER = "@placeholder";
const DEFAULT_SOURCE_SCHEMA_ID = "_SRC-node";
const CONTENT_PLACEHOLDER = "{content}";
const SOURCE_PLACEHOLDER = "{source}";

type NodeFormat = Pick<DiscourseNode, "format">;

export const schemaHasSourceSlot = (schema: NodeFormat): boolean =>
  (schema?.format ?? "").toLowerCase().includes(SOURCE_PLACEHOLDER);

const sourceNodeType = (allNodes: DiscourseNode[]): DiscourseNode | undefined =>
  allNodes.find((node) => node.text.toLowerCase() === "source");

// The node type a sourceDocument slot points at.
export const sourceSlotSchemaId = (allNodes?: DiscourseNode[]): string =>
  sourceNodeType(allNodes ?? getDiscourseNodes())?.type ??
  DEFAULT_SOURCE_SCHEMA_ID;

// Compiled once per format: these are matched against every node's source.
const formatMatchers = new Map<string, RegExp>();
const matcherFor = (format: string): RegExp => {
  const cached = formatMatchers.get(format);
  if (cached) return cached;
  const matcher = getDiscourseNodeFormatExpression(format);
  formatMatchers.set(format, matcher);
  return matcher;
};

// A slot may only hold a discourse node: the database resolves its value to a concept,
// and a page that is not a discourse node has none, which would be stored as a null
// reference. Better to leave the slot out than to fill it with that.
//
// Which node type it is, we do not check, and that leniency is part of the hack: the
// Source type is recognised here by being named "source", and a graph coming from
// another app may well name it otherwise. Rejecting anything but a local "Source" node
// would silently drop those. This goes away with slots as a real node type setting.
const isDiscourseNodeTitle = (
  title: string,
  allNodes: DiscourseNode[],
): boolean =>
  allNodes
    .filter((n) => n.format !== "{content}") // exclude page and block
    .some((node) => matcherFor(node.format).test(title));

// The two RID shapes the database resolves (see rid_to_space_id_and_local_id). The
// shared parser is not used here: its fallback splits any string at its last slash, so
// it accepts values the database will fail to resolve.
const ORN_RID = /^orn:\w+(\.\w+)?:.+\/[^/]+$/;

const isHttpsRid = (value: string): boolean => {
  try {
    const { protocol, host } = new URL(value);
    const lastSlash = value.lastIndexOf("/");
    return (
      protocol === "https:" &&
      host !== "" &&
      lastSlash > "https://".length &&
      lastSlash < value.length - 1
    );
  } catch {
    return false;
  }
};

const isWellFormedRid = (value: string): boolean =>
  ORN_RID.test(value) || isHttpsRid(value);

// The page a node's {source} placeholder resolves to, when there is one: its uid, or
// the RID it is known by elsewhere when it was imported from another app. The
// placeholder is usually filled with a page reference, and a title holding a slash is
// a namespaced page rather than a source, so it is left alone.
export const sourceIdOfNode = (
  title: string,
  schema: NodeFormat | undefined,
  allNodes?: DiscourseNode[],
): string | undefined => {
  if (schema === undefined) return undefined;
  if (!schemaHasSourceSlot(schema)) return undefined;
  const sourceTitle = extractFieldFromTitle(title, schema, "source")
    ?.replace(/^\[\[(.*)\]\]$/s, "$1")
    .trim();
  // The missing-source placeholder page is never a real Source.
  if (
    !sourceTitle ||
    sourceTitle === MISSING_SOURCE_PLACEHOLDER ||
    sourceTitle.includes("/")
  )
    return undefined;
  if (!isDiscourseNodeTitle(sourceTitle, allNodes ?? getDiscourseNodes()))
    return undefined;
  const sourceUid = getPageUidByPageTitle(sourceTitle);
  if (!sourceUid) return undefined;
  const sourceRid = readImportedSourceIdentity(sourceUid)?.sourceNodeRid;
  return sourceRid !== undefined && isWellFormedRid(sourceRid)
    ? sourceRid
    : sourceUid;
};

const FILLABLE_PLACEHOLDERS = new Set([
  CONTENT_PLACEHOLDER,
  SOURCE_PLACEHOLDER,
]);

// Inverse of sourceUidOfNode, for the pull side: the local title of a node whose format
// names a source, built from its core title and the Source page's title. Null when the
// format has a placeholder neither fills, so the caller keeps the incoming title.
export const titleWithSource = ({
  format,
  coreTitle,
  sourceTitle,
}: {
  format: string;
  coreTitle: string;
  sourceTitle: string;
}): string | null => {
  const placeholders = (format.match(FORMAT_PLACEHOLDER) ?? []).map(
    (placeholder) => placeholder.toLowerCase(),
  );
  if (
    !placeholders.includes(CONTENT_PLACEHOLDER) ||
    placeholders.some((placeholder) => !FILLABLE_PLACEHOLDERS.has(placeholder))
  )
    return null;
  return format.replace(FORMAT_PLACEHOLDER, (placeholder) =>
    placeholder.toLowerCase() === CONTENT_PLACEHOLDER
      ? coreTitle
      : `[[${sourceTitle}]]`,
  );
};
import { getSharedNodeByRid } from "@repo/database/lib/sharedNodes";
import getPageTitleByPageUid from "roamjs-components/queries/getPageTitleByPageUid";
import { readImportedSourceIdentity } from "./importedSourceIdentity";
import internalError from "./internalError";
import { getErrorMessage } from "./getErrorMessage";
import { materializeSharedNode } from "./materializeSharedNode";
import { resolveSharedNodeTypes } from "./resolveSharedNodeTypes";
import { getLoggedInClient } from "./supabaseContext";

export const REFRESH_ERROR_TYPE = "Imported node refresh failed";
const REFRESH_ERROR_OPERATION = "refresh-imported-node";

type RefreshImportedNodeResult = {
  status: "refreshed" | "skipped" | "failed";
  message: string;
  warning?: string;
};

export const refreshImportedNode = async ({
  pageUid,
  force,
}: {
  pageUid: string;
  force: boolean;
}): Promise<RefreshImportedNodeResult> => {
  try {
    const title = getPageTitleByPageUid(pageUid);
    const identity = readImportedSourceIdentity(pageUid);
    if (!identity)
      return {
        status: "failed",
        message: `"${title}" has no stored source identity, so it cannot be refreshed.`,
      };

    const client = await getLoggedInClient();
    if (!client)
      return {
        status: "failed",
        message: "Could not connect to shared persistence.",
      };

    const sharedNode = await getSharedNodeByRid({
      client,
      rid: identity.sourceNodeRid,
    });
    if (!sharedNode)
      return {
        status: "failed",
        message: `The source of "${title}" is no longer shared with your groups, so it cannot be refreshed.`,
      };

    const nodeTypesBySchemaId = await resolveSharedNodeTypes({
      client,
      sharedNodes: [sharedNode],
    });
    const result = await materializeSharedNode({
      client,
      sharedNode,
      nodeType: nodeTypesBySchemaId.get(sharedNode.schemaId),
      force,
    });
    if (!result.success) {
      internalError({
        error: new Error(result.error.message),
        type: REFRESH_ERROR_TYPE,
        context: {
          operation: REFRESH_ERROR_OPERATION,
          pageUid,
          stage: result.error.stage,
        },
        sendEmail: false,
      });
      return { status: "failed", message: result.error.message };
    }
    if (result.pageUid !== pageUid)
      return {
        status: "failed",
        message: `A different page ("${getPageTitleByPageUid(result.pageUid)}") is linked to the same source and was refreshed instead.`,
      };
    if (result.action === "skipped")
      return {
        status: "skipped",
        message: `"${sharedNode.title}" is already up to date.`,
      };
    return {
      status: "refreshed",
      message: `Refreshed "${sharedNode.title}" from ${sharedNode.spaceName}.`,
      ...(result.warning ? { warning: result.warning } : {}),
    };
  } catch (error) {
    internalError({
      error,
      type: REFRESH_ERROR_TYPE,
      context: { operation: REFRESH_ERROR_OPERATION, pageUid },
      sendEmail: false,
    });
    return {
      status: "failed",
      message: `Could not refresh this page: ${getErrorMessage(error)}`,
    };
  }
};
      }),
  });
};

const getAllUsers = async (): Promise<LocalAccountDataInput[]> => {
  const query = `[:find ?author_local_id ?author_name
  :keys author_local_id name
  :where
    [?user-eid :user/uid ?author_local_id]
    [(get-else $ ?user-eid :user/display-name "") ?author_name]
]`;
  const result = (await window.roamAlphaAPI.data.backend.q(
    query,
  )) as unknown[] as {
    author_local_id: string;
    name: string;
  }[];
  return result.map((user) => ({
    account_local_id: user.author_local_id,
    name: user.name,
    email: null,
    email_trusted: null,
    space_editor: null,
    permissions: null,
  }));
};

const upsertUsers = async (
  users: LocalAccountDataInput[],
  supabaseClient: DGSupabaseClient,
  context: SupabaseContext,
) => {
  const { error } = await supabaseClient.rpc("upsert_accounts_in_space", {
    accounts: users,
    space_id_: context.spaceId,
  });
  if (error) {
    console.error("upsert_accounts_in_space failed:", error);
    throw error;
  }
};

