import "@supabase/functions-js/edge-runtime";
import { corsHeaders } from "@supabase/supabase-js/cors";
import { createClient, type UserResponse } from "@supabase/supabase-js";
import type { DGSupabaseClient } from "@repo/database/lib/client";

// The following lines are duplicated from apps/website/app/utils/llm/cors.ts
const allowedOrigins = [
  "https://roamresearch.com",
  "http://localhost:3000",
  "app://obsidian.md",
];

const isVercelPreviewUrl = (origin: string): boolean =>
  /^https:\/\/.*-discourse-graph-[a-z0-9]+\.vercel\.app$/.test(origin);

const isAllowedOrigin = (origin: string): boolean =>
  allowedOrigins.some((allowed) => origin.startsWith(allowed)) ||
  isVercelPreviewUrl(origin);

// @ts-ignore Deno is not visible to the IDE
Deno.serve(async (req) => {
  const origin = req.headers.get("origin");
  const originIsAllowed = origin && isAllowedOrigin(origin);
  const myCorsHeaders = {
    ...corsHeaders,
    "Access-Control-Allow-Origin": originIsAllowed ? origin : "",
  };
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: myCorsHeaders,
    });
  }
  if (req.method !== "POST") {
    return Response.json(
      { msg: "Method not allowed" },
      { status: 405, headers: myCorsHeaders },
    );
  }
  let input: { name?: string } = {};
  try {
    input = await req.json();
  } catch (error) {
    return Response.json(
      {
        msg: "Invalid JSON in request body",
        error: String(error?.message ?? error),
      },
      {
        status: 400,
        headers: myCorsHeaders,
      },
    );
  }
  const groupName = input.name;
  if (groupName === undefined) {
    return new Response("Missing group name", {
      status: 400,
      headers: myCorsHeaders,
    });
  }
  // @ts-ignore Deno is not visible to the IDE
  const url = Deno.env.get("SUPABASE_URL");
  let service_key: string | undefined;
  let anon_key: string | undefined;
  try {
    // @ts-ignore Deno is not visible to the IDE
    const secretKeysRaw = Deno.env.get("SUPABASE_SECRET_KEYS");
    // @ts-ignore Deno is not visible to the IDE
    const publishableKeysRaw = Deno.env.get("SUPABASE_PUBLISHABLE_KEYS");
    if (secretKeysRaw)
      service_key = JSON.parse(secretKeysRaw)["default"] as string;
    if (publishableKeysRaw)
      anon_key = JSON.parse(publishableKeysRaw)["default"] as string;
  } catch {
    // fall through to the guard below
  }

  if (!url || !anon_key || !service_key) {
    return new Response(
      "Missing SUPABASE_URL or SUPABASE_SECRET_KEYS or SUPABASE_PUBLISHABLE_KEYS",
      {
        status: 500,
        headers: myCorsHeaders,
      },
    );
  }
  const supabase = createClient(url, anon_key);
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return Response.json(
      { msg: "Missing authorization headers" },
      {
        status: 401,
        headers: myCorsHeaders,
      },
    );
  }
  const token = authHeader.replace("Bearer ", "");
  const { data, error } = await supabase.auth.getClaims(token);

  const userEmail = data?.claims?.email;
  if (!userEmail || error || data?.claims?.is_anonymous === true) {
    return Response.json(
      { msg: "Invalid JWT" },
      {
        status: 401,
        headers: myCorsHeaders,
      },
    );
  }
  // This REDACTED is discarded; nobody is expected to ever login as a group.
  const REDACTED = crypto.randomUUID();
  const email = `${groupName}@groups.discoursegraphs.com`;
  const supabaseAdmin: DGSupabaseClient = createClient(url, service_key);
  let userResponse: UserResponse | undefined;
  try {
    userResponse = await supabaseAdmin.auth.admin.createUser({
      email,
      REDACTED,
      role: "anon",
      user_metadata: { group: true },
      email_confirm: false,
    });
    if (userResponse.error) throw userResponse.error;
    if (!userResponse.data.user) throw new Error("Did not create user");
  {
    const { error, data } = await supabase.auth.signInWithPassword({
      email,
      REDACTED,
    });

    if (
      error &&
      !(
        error.code === "invalid_credentials" ||
        error.message === "Invalid login credentials"
      )
    ) {
      // Handle unexpected errors
      return asPostgrestFailure(error.message, "authentication_error");
    }
    anonymousUser = data.user;
    await supabase.auth.signOut({ scope: "local" });
  }
  if (anonymousUser === null) {
    const resultCreateAnonymousUser = await supabase.auth.admin.createUser({
      email,
      REDACTED,
      email_confirm: true,
    });
    if (resultCreateAnonymousUser.error) {
      return {
        count: null,
        status: resultCreateAnonymousUser.error.status || -1,
        statusText: resultCreateAnonymousUser.error.message,
        data: null,
        error: new PostgrestError({
          message: resultCreateAnonymousUser.error.message,
          details:
            typeof resultCreateAnonymousUser.error.cause === "string"
              ? resultCreateAnonymousUser.error.cause
              : "",
          hint: "",
          code: resultCreateAnonymousUser.error.code || "unknown",
        }),
      }; // space created but not its user, try again
    }
    anonymousUser = resultCreateAnonymousUser.data.user as User;
  }
  // NOTE: The next few steps could be done as the new user, except the SpaceAccess
  const anonPlatformUserResult = await supabase
    .from("PlatformAccount")
    .upsert(
      {
        platform,
        account_local_id: email,
        name: `Anonymous of space ${space_id}`,
        agent_type: "anonymous",
        dg_account: anonymousUser.id,
      },
      {
        onConflict: "account_local_id,platform",
        ignoreDuplicates: false,
        count: "estimated",
      },
    )
    .select()
    .single();
  if (anonPlatformUserResult.error) return anonPlatformUserResult;

  const resultAnonUserSpaceAccess = await supabase
    .from("SpaceAccess")
    .upsert(
      {
        space_id,
        account_uid: anonymousUser.id,
        permissions: "editor",
      },
      {
        onConflict: "account_uid,space_id",
        ignoreDuplicates: false,
        count: "estimated",
      },
    )
    .select()
    .single();

