        AND account_local_id = public.get_space_anonymous_email(OLD.platform, OLD.id);
    RETURN NEW;
END;
$$;

CREATE TRIGGER on_delete_space_trigger AFTER DELETE ON public."Space" FOR EACH ROW EXECUTE FUNCTION public.after_delete_space();

