const getClients = (): { service: Client; target: string } => {
  const target = assertLocalTarget();
  const publishableKey = getRequiredEnv("SUPABASE_PUBLISHABLE_KEY");
  const serviceKey = getRequiredEnv("SUPABASE_SERVICE_ROLE_KEY");
  return {
    target,
    service: createClient<Database, "public">(target, serviceKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    }),
  };
};

const assertNoError = ({ error, context }: { error: unknown; context: string }): void => {
  if (error) throw new Error(`${context}: ${String(error)}`);
};

const createUser = async ({
  service,
  runId,
  role,
}: {
  service: Client;
  runId: string;
  role: string;
}): Promise<{ email: string; id: string }> => {
  const email = `${runId}-${role}@validation.local`;
  const response = await service.auth.admin.createUser({
    email,
    password: REDACTED,
    email_confirm: true,
  });
  assertNoError({ error: response.error, context: `create ${role} user` });
  const id = response.data.user?.id;
  if (!id) throw new Error(`create ${role} user returned no user`);
  return { email, id };
};

const signIn = async ({
  email,
  target,
}: {
  email: string;
  target: string;
}): Promise<Client> => {
  const client = createClient<Database, "public">(
    target,
    getRequiredEnv("SUPABASE_PUBLISHABLE_KEY"),
    { auth: { autoRefreshToken: false, persistSession: false } },
  );
  const response = await client.auth.signInWithPassword({ email, password: REDACTED });
  assertNoError({ error: response.error, context: `sign in ${email}` });
  return client;
};

const createSpace = async ({
  service,
  runId,
  suffix,
}: {
  service: Client;
  runId: string;
  suffix: string;
}): Promise<number> => {
  const response = await service
    .from("Space")
    .insert({
      name: `${runId} ${suffix}`,
      platform: "Roam",
      url: `https://validation.local/${runId}/${suffix}`,
    })
    .select("id")
    .single();
  assertNoError({ error: response.error, context: `create ${suffix} space` });
  if (response.data?.id === undefined) throw new Error(`create ${suffix} space returned no id`);
  return response.data.id;
};

const createPlatformAccount = async ({
  service,
  userId,
  runId,
  role,
}: {
  service: Client;
  userId: string;
  runId: string;
  role: string;
}): Promise<string> => {
  const localId = `${runId}-${role}`;
  const response = await service.from("PlatformAccount").insert({
    account_local_id: localId,
    dg_account: userId,
    name: `${runId} ${role}`,
    platform: "Roam",
  });
  assertNoError({ error: response.error, context: `create ${role} platform account` });
  return localId;
};

const grantSpaceAccess = async ({
  accountId,
  service,
  spaceId,
}: {
  accountId: string;
  service: Client;
  spaceId: number;
}): Promise<void> => {
  const response = await service.from("SpaceAccess").insert({
    account_uid: accountId,
    permissions: "editor",
    space_id: spaceId,
  });
  assertNoError({ error: response.error, context: "seed permitted space access" });
};

const getSpaceGrant = async ({
  accountId,
  service,
  spaceId,
}: {
  accountId: string;
  service: Client;
  spaceId: number;
}): Promise<unknown> => {
  const response = await service
    .from("SpaceAccess")
    .select("permissions")
    .eq("account_uid", accountId)
    .eq("space_id", spaceId)
    .maybeSingle();
  assertNoError({ error: response.error, context: "read space access" });
  return response.data;
};

const cleanRun = async ({
  groupIds,
  service,
  spaceIds,
  userIds,
}: {
  groupIds: string[];
  service: Client;
  spaceIds: number[];
  userIds: string[];
}): Promise<{ errors: string[]; verified: boolean }> => {
  const errors: string[] = [];
  const remove = async (context: string, operation: () => Promise<{ error: unknown }>): Promise<void> => {
    try {
      const response = await operation();
      if (response.error) errors.push(`${context}: ${String(response.error)}`);
    } catch (error) {
      errors.push(`${context}: ${String(error)}`);
    }
  };
  if (groupIds.length) {
    await remove("delete group memberships", async () =>
      service.from("group_membership").delete().in("group_id", groupIds),
    );
  }
  if (spaceIds.length) {
    await remove("delete local access", async () =>
      service.from("LocalAccess").delete().in("space_id", spaceIds),
    );
    await remove("delete space access", async () =>
      service.from("SpaceAccess").delete().in("space_id", spaceIds),
    );
    await remove("delete spaces", async () =>
      service.from("Space").delete().in("id", spaceIds),
    );
  }
  if (userIds.length) {
    await remove("delete platform accounts", async () =>
      service.from("PlatformAccount").delete().in("dg_account", userIds),
    );
    for (const userId of userIds) {
      await remove(`delete auth user ${userId}`, async () =>
        service.auth.admin.deleteUser(userId),
      );
    }
  }
  const residue = await Promise.all([
    service.from("Space").select("id", { count: "exact", head: true }).in("id", spaceIds),
    service
      .from("group_membership")
      .select("group_id", { count: "exact", head: true })
      .in("group_id", groupIds),
  ]);
  for (const [index, response] of residue.entries()) {
    if (response.error) errors.push(`verify cleanup ${index}: ${String(response.error)}`);
  }
  const verified = errors.length === 0 && residue.every((response) => response.count === 0);
  return { errors, verified };
};

const runSec01 = async ({ service, target, runId }: { service: Client; target: string; runId: string }): Promise<RunRecord> => {
  const users: { email: string; id: string }[] = [];
  const spaces: number[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  try {
    const [owner, member, outsider, controlCandidate] = await Promise.all(
      ["owner", "member", "outsider", "control-candidate"].map(async (role) => {
        const user = await createUser({ service, runId, role });
        users.push(user);
        return user;
      }),
    );
    const spaceId = await createSpace({ service, runId, suffix: "sec01-target" });
    spaces.push(spaceId);
    const localIds = await Promise.all(
      [owner, member, outsider, controlCandidate].map(async (user, index) =>
        createPlatformAccount({
          service,
          userId: user.id,
          runId,
          role: ["owner", "member", "outsider", "control-candidate"][index],
        }),
      ),
    );
    await Promise.all([
      grantSpaceAccess({ service, accountId: owner.id, spaceId }),
      grantSpaceAccess({ service, accountId: member.id, spaceId }),
    ]);
    const outsiderClient = await signIn({ email: outsider.email, target });
    const before = await getSpaceGrant({ service, accountId: outsider.id, spaceId });
    assert.equal(before, null, "outsider unexpectedly had target-space access before the attempt");
    const outsiderAttempt = await outsiderClient.rpc("upsert_account_in_space", {
      local_account: { account_local_id: localIds[2], name: `${runId} outsider`, permissions: "editor" },
      space_id_: spaceId,
    });
    const after = await getSpaceGrant({ service, accountId: outsider.id, spaceId });
    const memberClient = await signIn({ email: member.email, target });
    const permittedControl = await memberClient.rpc("upsert_account_in_space", {
      local_account: { account_local_id: localIds[3], name: `${runId} control candidate`, permissions: "editor" },
      space_id_: spaceId,
    });
    const permittedGrant = await getSpaceGrant({ service, accountId: controlCandidate.id, spaceId });
    observation = {
      outsiderAttempt: { error: outsiderAttempt.error?.message ?? null, returnedAccountId: outsiderAttempt.data ?? null },
      outsiderGrantAfter: after,
      permittedMemberControl: { error: permittedControl.error?.message ?? null, grant: permittedGrant },
      hypothesisReproduced: outsiderAttempt.error === null && after !== null,
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds: [],
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return { candidate: CANDIDATE, caseId: "SEC-01", cleanup, createdAt: new Date().toISOString(), observation, runId, target };
};

const runSec02 = async ({ service, target, runId }: { service: Client; target: string; runId: string }): Promise<RunRecord> => {
  const users: { email: string; id: string }[] = [];
  const spaces: number[] = [];
  const groupIds: string[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  try {
    const roles = ["outsider", "protected-group", "positive-group", "positive-admin", "positive-member", "former-member", "rejoin-group"];
    const createdUsers = await Promise.all(
      roles.map(async (role) => {
        const user = await createUser({ service, runId, role });
        users.push(user);
        return user;
      }),
    );
    const [outsider, protectedGroup, positiveGroup, positiveAdmin, positiveMember, formerMember, rejoinGroup] = createdUsers;
    groupIds.push(protectedGroup.id, positiveGroup.id, rejoinGroup.id);
    const protectedSpaceId = await createSpace({ service, runId, suffix: "sec02-protected" });
    spaces.push(protectedSpaceId);
    await grantSpaceAccess({ service, accountId: protectedGroup.id, spaceId: protectedSpaceId });
    const outsiderClient = await signIn({ email: outsider.email, target });
    const freshAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: protectedGroup.id,
      member_id: outsider.id,
    });
    const inheritedSpaceRead = await outsiderClient
      .from("Space")
      .select("id")
      .eq("id", protectedSpaceId)
      .maybeSingle();
    const seedAdmin = await service.from("group_membership").insert({
      admin: true,
      group_id: positiveGroup.id,
      member_id: positiveAdmin.id,
    });
    assertNoError({ error: seedAdmin.error, context: "seed positive-control group admin" });
    const positiveAdminClient = await signIn({ email: positiveAdmin.email, target });
    const permittedControl = await positiveAdminClient.from("group_membership").insert({
      admin: false,
      group_id: positiveGroup.id,
      member_id: positiveMember.id,
    });
    const seedFormerMember = await service.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: formerMember.id,
    });
    assertNoError({ error: seedFormerMember.error, context: "seed former member" });
    const removeFormerMember = await service
      .from("group_membership")
      .delete()
      .eq("group_id", rejoinGroup.id)
      .eq("member_id", formerMember.id);
    assertNoError({ error: removeFormerMember.error, context: "empty rejoin group" });
    const rejoinAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: outsider.id,
    });
    observation = {
      freshAttempt: { error: freshAttempt.error?.message ?? null },
      inheritedProtectedSpaceRead: { error: inheritedSpaceRead.error?.message ?? null, visible: inheritedSpaceRead.data !== null },
      permittedAdminControl: { error: permittedControl.error?.message ?? null },
      emptyGroupRejoinAttempt: { error: rejoinAttempt.error?.message ?? null },
      hypothesisReproduced:
        freshAttempt.error === null && inheritedSpaceRead.data !== null && rejoinAttempt.error === null,
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds,
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return { candidate: CANDIDATE, caseId: "SEC-02", cleanup, createdAt: new Date().toISOString(), observation, runId, target };
};

const writeRecord = async (record: RunRecord): Promise<void> => {
  const outputPath = getRequiredEnv("DG_VALIDATION_RESULT_PATH");
  const resultsRoot = resolve("/mnt/data/projects/dg-validation-eng-1883/runs/");
  if (!resolve(outputPath).startsWith(resultsRoot)) {
    throw new Error(`Refusing to write result outside ${resultsRoot}`);
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${JSON.stringify(record, null, 2)}\n`, { mode: 0o600 });
};

const main = async (): Promise<void> => {
  const caseId = getCaseId();
  const { service, target } = getClients();
  const runId = `eng1883-${caseId.toLowerCase()}-${crypto.randomUUID().slice(0, 8)}`;
  const record = caseId === "SEC-01" ? await runSec01({ service, target, runId }) : await runSec02({ service, target, runId });
  await writeRecord(record);
  if (!record.cleanup.verified) process.exitCode = 2;
  if (record.observation.hypothesisReproduced !== true) process.exitCode = 1;
};

void main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 2;
});

