    const createdUsers = await Promise.all(
      roles.map(async (role) => {
        const user = await createUser({ service, runId, role });
        users.push(user);
        return user;
      }),
    );
    const [outsider, protectedGroup, positiveGroup, positiveAdmin, positiveMember, formerMember, rejoinGroup] = createdUsers;
    groupIds.push(protectedGroup.id, positiveGroup.id, rejoinGroup.id);
    const protectedSpaceId = await createSpace({ service, runId, suffix: "sec02-protected" });
    spaces.push(protectedSpaceId);
    await grantSpaceAccess({ service, accountId: protectedGroup.id, spaceId: protectedSpaceId });
    const outsiderClient = await signIn({ email: outsider.email, target });
    const freshAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: protectedGroup.id,
      member_id: outsider.id,
    });
    const inheritedSpaceRead = await outsiderClient
      .from("Space")
      .select("id")
      .eq("id", protectedSpaceId)
      .maybeSingle();
    const seedAdmin = await service.from("group_membership").insert({
      admin: true,
      group_id: positiveGroup.id,
      member_id: positiveAdmin.id,
    });
    assertNoError({ error: seedAdmin.error, context: "seed positive-control group admin" });
