      admin: false,
      group_id: positiveGroup.id,
      member_id: positiveMember.id,
    });
    const seedFormerMember = await service.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: formerMember.id,
    });
    assertNoError({ error: seedFormerMember.error, context: "seed former member" });
    const removeFormerMember = await service
      .from("group_membership")
      .delete()
      .eq("group_id", rejoinGroup.id)
      .eq("member_id", formerMember.id);
    assertNoError({ error: removeFormerMember.error, context: "empty rejoin group" });
    const rejoinAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: rejoinGroup.id,
      member_id: outsider.id,
    });
    observation = {
      freshAttempt: { error: freshAttempt.error?.message ?? null },
      inheritedProtectedSpaceRead: { error: inheritedSpaceRead.error?.message ?? null, visible: inheritedSpaceRead.data !== null },
      permittedAdminControl: { error: permittedControl.error?.message ?? null },
      emptyGroupRejoinAttempt: { error: rejoinAttempt.error?.message ?? null },
      hypothesisReproduced:
        freshAttempt.error === null && inheritedSpaceRead.data !== null && rejoinAttempt.error === null,
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds,
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return { candidate: CANDIDATE, caseId: "SEC-02", cleanup, createdAt: new Date().toISOString(), observation, runId, target };
};

const writeRecord = async (record: RunRecord): Promise<void> => {
  const outputPath = getRequiredEnv("DG_VALIDATION_RESULT_PATH");
  const resultsRoot = resolve("/mnt/data/projects/dg-validation-eng-1883/runs/");
  if (!resolve(outputPath).startsWith(resultsRoot)) {
    throw new Error(`Refusing to write result outside ${resultsRoot}`);
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${JSON.stringify(record, null, 2)}\n`, { mode: 0o600 });
};

const main = async (): Promise<void> => {
  const caseId = getCaseId();
  const { service, target } = getClients();
  const runId = `eng1883-${caseId.toLowerCase()}-${crypto.randomUUID().slice(0, 8)}`;
  const record = caseId === "SEC-01" ? await runSec01({ service, target, runId }) : await runSec02({ service, target, runId });
  await writeRecord(record);
  if (!record.cleanup.verified) process.exitCode = 2;
  if (record.observation.hypothesisReproduced !== true) process.exitCode = 1;
};

void main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 2;
});

