  groupIds: string[];
  service: Client;
  spaceIds: number[];
  userIds: string[];
}): Promise<{ errors: string[]; verified: boolean }> => {
  const errors: string[] = [];
  const remove = async (context: string, operation: () => Promise<{ error: unknown }>): Promise<void> => {
    try {
      const response = await operation();
      if (response.error) errors.push(`${context}: ${String(response.error)}`);
    } catch (error) {
      errors.push(`${context}: ${String(error)}`);
    }
  };
  if (groupIds.length) {
    await remove("delete group memberships", async () =>
      service.from("group_membership").delete().in("group_id", groupIds),
    );
  }
  if (spaceIds.length) {
    await remove("delete local access", async () =>
      service.from("LocalAccess").delete().in("space_id", spaceIds),
    );
    await remove("delete space access", async () =>
      service.from("SpaceAccess").delete().in("space_id", spaceIds),
    );
    await remove("delete spaces", async () =>
      service.from("Space").delete().in("id", spaceIds),
    );
  }
  if (userIds.length) {
    await remove("delete platform accounts", async () =>
      service.from("PlatformAccount").delete().in("dg_account", userIds),
    );
    for (const userId of userIds) {
      await remove(`delete auth user ${userId}`, async () =>
        service.auth.admin.deleteUser(userId),
      );
    }
  }
  const residue = await Promise.all([
    service.from("Space").select("id", { count: "exact", head: true }).in("id", spaceIds),
    service
      .from("group_membership")
      .select("group_id", { count: "exact", head: true })
      .in("group_id", groupIds),
  ]);
  for (const [index, response] of residue.entries()) {
    if (response.error) errors.push(`verify cleanup ${index}: ${String(response.error)}`);
  }
  const verified = errors.length === 0 && residue.every((response) => response.count === 0);
  return { errors, verified };
};

const runSec01 = async ({ service, target, runId }: { service: Client; target: string; runId: string }): Promise<RunRecord> => {
  const users: { email: string; id: string }[] = [];
  const spaces: number[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  try {
    const [owner, member, outsider, controlCandidate] = await Promise.all(
      ["owner", "member", "outsider", "control-candidate"].map(async (role) => {
        const user = await createUser({ service, runId, role });
        users.push(user);
        return user;
      }),
    );
    const spaceId = await createSpace({ service, runId, suffix: "sec01-target" });
    spaces.push(spaceId);
    const localIds = await Promise.all(
      [owner, member, outsider, controlCandidate].map(async (user, index) =>
        createPlatformAccount({
          service,
          userId: user.id,
          userId: user.id,
          runId,
          role: ["owner", "member", "outsider", "control-candidate"][index],
        }),
      ),
    );
    await Promise.all([
      grantSpaceAccess({ service, accountId: owner.id, spaceId }),
      grantSpaceAccess({ service, accountId: member.id, spaceId }),
    ]);
    const outsiderClient = await signIn({ email: outsider.email, target });
    const before = await getSpaceGrant({ service, accountId: outsider.id, spaceId });
    assert.equal(before, null, "outsider unexpectedly had target-space access before the attempt");
    const outsiderAttempt = await outsiderClient.rpc("upsert_account_in_space", {
      local_account: { account_local_id: localIds[2], name: `${runId} outsider`, permissions: "editor" },
      space_id_: spaceId,
    });
    const after = await getSpaceGrant({ service, accountId: outsider.id, spaceId });
    const memberClient = await signIn({ email: member.email, target });
    const permittedControl = await memberClient.rpc("upsert_account_in_space", {
      local_account: { account_local_id: localIds[3], name: `${runId} control candidate`, permissions: "editor" },
      space_id_: spaceId,
    });
    const permittedGrant = await getSpaceGrant({ service, accountId: controlCandidate.id, spaceId });
    observation = {
      outsiderAttempt: { error: outsiderAttempt.error?.message ?? null, returnedAccountId: outsiderAttempt.data ?? null },
      outsiderGrantAfter: after,
      permittedMemberControl: { error: permittedControl.error?.message ?? null, grant: permittedGrant },
      hypothesisReproduced: outsiderAttempt.error === null && after !== null,
    };
  } finally {
    cleanup.attempted = true;
