      i < noteParts.length &&
      i < targetParts.length &&
      noteParts[i] === targetParts[i]
    ) {
      i++;
    }
    const ups = noteParts.length - i;
    const down = targetParts.slice(i);
    const segments = [...Array(ups).fill(".."), ...down];
