    baseDir: string,
    relativePath: string,
  ): string => {
    const baseParts = baseDir ? baseDir.split("/").filter(Boolean) : [];
    const pathParts = relativePath.replace(/\/+/g, "/").trim().split("/");
    const result = [...baseParts];
    for (const part of pathParts) {
      if (part === "..") {
        result.pop();
