import type { Rid } from "@repo/database/crossAppContracts";
import {
  DISCOURSE_GRAPH_PROP_NAME,
  IMPORTED_FROM_PROP_KEY,
} from "./createReifiedBlock";
import getBlockProps, { isJsonObject, type json } from "./getBlockProps";
import { setBlockPropsAsync } from "./setBlockProps";

export type ImportedSourceIdentity = {
  sourceModifiedAt: string;
  sourceNodeRid: Rid;
};

const SOURCE_NODE_RID_KEY = "sourceNodeRid";
const SOURCE_MODIFIED_AT_KEY = "sourceModifiedAt";

export const parseSourceIdentity = (
  importedFrom: json | undefined,
): ImportedSourceIdentity | undefined => {
  if (!isJsonObject(importedFrom)) return undefined;

  const sourceModifiedAt = importedFrom[SOURCE_MODIFIED_AT_KEY];
  const sourceNodeRid = importedFrom[SOURCE_NODE_RID_KEY];
  if (typeof sourceModifiedAt !== "string" || typeof sourceNodeRid !== "string")
    return undefined;

  return { sourceModifiedAt, sourceNodeRid };
};

export const parseImportedSourceIdentity = (
  props: Record<string, json>,
): ImportedSourceIdentity | undefined => {
  const discourseGraphProps = props[DISCOURSE_GRAPH_PROP_NAME];
  if (!isJsonObject(discourseGraphProps)) return undefined;

  return parseSourceIdentity(discourseGraphProps[IMPORTED_FROM_PROP_KEY]);
};

export const readImportedSourceIdentity = (
  pageUid: string,
): ImportedSourceIdentity | undefined =>
  parseImportedSourceIdentity(getBlockProps(pageUid));

export const writeImportedSourceIdentity = async ({
  pageUid,
  sourceModifiedAt,
  sourceNodeRid,
}: {
  pageUid: string;
  sourceModifiedAt: string;
  sourceNodeRid: string;
}): Promise<void> => {
  const existing = getBlockProps(pageUid)[DISCOURSE_GRAPH_PROP_NAME];
  const discourseGraphProps = isJsonObject(existing) ? existing : {};

  await setBlockPropsAsync(pageUid, {
    [DISCOURSE_GRAPH_PROP_NAME]: {
      ...discourseGraphProps,
      [IMPORTED_FROM_PROP_KEY]: {
        [SOURCE_MODIFIED_AT_KEY]: sourceModifiedAt,
        [SOURCE_NODE_RID_KEY]: sourceNodeRid,
      },
    },
  });
};

export const getImportedSourceRids = async (): Promise<Set<string>> => {
  const query = `[:find [?rid ...]
    :where
      [?page :block/props ?props]
      [(get ?props :${DISCOURSE_GRAPH_PROP_NAME}) ?dgData]
      [(get ?dgData :${IMPORTED_FROM_PROP_KEY}) ?importedFrom]
      [(get ?importedFrom :${SOURCE_NODE_RID_KEY}) ?rid]]`;
  const result = (await window.roamAlphaAPI.data.async.q(query)) as unknown[];

  return new Set(
    result.filter((rid): rid is string => typeof rid === "string"),
  );
};

export const getImportedNodeUids = async (): Promise<Set<string>> => {
  const query = `[:find [?uid ...]
    :where
      [?page :block/uid ?uid]
      [?page :block/props ?props]
      [(get ?props :${DISCOURSE_GRAPH_PROP_NAME}) ?dgData]
      [(get ?dgData :${IMPORTED_FROM_PROP_KEY}) ?importedFrom]
      [(get ?importedFrom :${SOURCE_NODE_RID_KEY}) ?rid]]`;
  const result = (await window.roamAlphaAPI.data.async.q(query)) as unknown[];

  return new Set(
    result.filter((uid): uid is string => typeof uid === "string"),
  );
};

export const findImportedNodeUidBySourceRid = async (
  sourceNodeRid: string,
): Promise<string | null> => {
  const query = `[:find ?uid
    :in $ ?sourceNodeRid
    :where
      [?page :block/uid ?uid]
      [?page :block/props ?props]
      [(get ?props :${DISCOURSE_GRAPH_PROP_NAME}) ?dgData]
      [(get ?dgData :${IMPORTED_FROM_PROP_KEY}) ?importedFrom]
      [(get ?importedFrom :${SOURCE_NODE_RID_KEY}) ?sourceNodeRid]]`;
  const result = (await window.roamAlphaAPI.data.async.q(
    query,
    sourceNodeRid,
  )) as unknown[];

  const [first] = result;
  if (!Array.isArray(first)) return null;
  const [uid] = first as unknown[];
  return typeof uid === "string" ? uid : null;
};

import { beforeEach, describe, expect, it, vi } from "vitest";
import { getImportedNodeUids } from "~/utils/importedSourceIdentity";
import { refreshAllImportedNodes } from "~/utils/refreshAllImportedNodes";
import { refreshImportedNode } from "~/utils/refreshImportedNode";

vi.mock("~/utils/importedSourceIdentity", () => ({
  getImportedNodeUids: vi.fn(),
}));
vi.mock("~/utils/refreshImportedNode", () => ({
  refreshImportedNode: vi.fn(),
}));

const mockedGetImportedNodeUids = vi.mocked(getImportedNodeUids);
const mockedRefreshImportedNode = vi.mocked(refreshImportedNode);

beforeEach(() => {
  vi.clearAllMocks();
});

describe("refreshAllImportedNodes", () => {
  it("refreshes every imported node without forcing and tallies the outcomes", async () => {
    mockedGetImportedNodeUids.mockResolvedValue(
      new Set(["uid-1", "uid-2", "uid-3", "uid-4"]),
    );
    mockedRefreshImportedNode
      .mockResolvedValueOnce({ status: "refreshed", message: "Refreshed." })
      .mockResolvedValueOnce({ status: "skipped", message: "Up to date." })
      .mockResolvedValueOnce({ status: "failed", message: "Not shared." })
      .mockResolvedValueOnce({ status: "refreshed", message: "Refreshed." });

    await expect(refreshAllImportedNodes()).resolves.toEqual({
      refreshed: 2,
      skipped: 1,
      failed: 1,
      warnings: [],
    });
    expect(mockedRefreshImportedNode.mock.calls).toEqual([
      [{ pageUid: "uid-1", force: false }],
      [{ pageUid: "uid-2", force: false }],
      [{ pageUid: "uid-3", force: false }],
      [{ pageUid: "uid-4", force: false }],
    ]);
  });

  it("returns zero counts when the graph has no imported nodes", async () => {
    mockedGetImportedNodeUids.mockResolvedValue(new Set());

    await expect(refreshAllImportedNodes()).resolves.toEqual({
      refreshed: 0,
      skipped: 0,
      failed: 0,
      warnings: [],
    });
    expect(mockedRefreshImportedNode).not.toHaveBeenCalled();
  });

  it("preserves source warnings alongside successful refresh counts", async () => {
    mockedGetImportedNodeUids.mockResolvedValue(new Set(["uid-1", "uid-2"]));
    mockedRefreshImportedNode
      .mockResolvedValueOnce({
        status: "refreshed",
        message: 'Refreshed "Evidence" from Research vault.',
        warning:
          "Its source is not in this graph, so its title was kept as published.",
      })
      .mockResolvedValueOnce({ status: "refreshed", message: "Refreshed." });

    await expect(refreshAllImportedNodes()).resolves.toEqual({
      refreshed: 2,
      skipped: 0,
      failed: 0,
      warnings: [
        'Refreshed "Evidence" from Research vault. Its source is not in this graph, so its title was kept as published.',
      ],
    });
  });
});
