import { describe, expect, it } from "vitest";
import type { App, TFile } from "obsidian";
import { updateMarkdownAssetLinks } from "~/utils/importNodes";

const targetFile = {
  path: "import/Roam graph/Imported note.md",
} as TFile;

const app = {
  metadataCache: {
    getFirstLinkpathDest: () => null,
  },
} as unknown as App;

describe("updateMarkdownAssetLinks", () => {
  it("leaves a mapped Roam PDF macro remote", () => {
    const remotePdf = "https://files.roamresearch.com/example.pdf";

    expect(
      updateMarkdownAssetLinks({
        app,
        content: `{{[[pdf]]: ${remotePdf}}}`,
        oldPathToNewPath: new Map([[remotePdf, "import/Roam graph/assets/example.pdf"]]),
        targetFile,
      }),
    ).toBe(`{{[[pdf]]: ${remotePdf}}}`);
  });

  it("keeps native Roam text syntax while rewriting only wiki links", () => {
    expect(
      updateMarkdownAssetLinks({
        app,
        content: "[[EVD]] - ^^highlight^^ - #[[tag]] - {{[[video]]: https://example.test/video}}",
        oldPathToNewPath: new Map(),
        targetFile,
      }),
    ).toBe(
      "[[EVD|EVD]] - ^^highlight^^ - #[[tag|tag]] - {{[[video]]: https://example.test/video}}",
    );
  });
});

