    await expect(
      materializeSharedNode({ client, sharedNode }),
    ).resolves.toEqual({
      success: true,
      action: "created",
      pageUid: GENERATED_PAGE_UID,
      sourceModifiedAt: sharedNode.lastModified,
      sourceNodeRid: sharedNode.rid,
      assets: NO_ASSETS,
