    publishedNodeSchemaUids: [],
    publishedNodeUids: [],
    publishedRelationTripleSchemaUids: [],
    publishedRelationUids: [],
    syncedNodeSchemaUids: [],
    syncedRelationUids: [],
    syncedRelationTripleSchemaUids: [],
    failedUpsertUids: [],
