import createBlock from "roamjs-components/writes/createBlock";
import createPage from "roamjs-components/writes/createPage";
import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";
import getBlockProps, { isJsonObject, type json } from "./getBlockProps";
import { setBlockPropsAsync } from "./setBlockProps";
import internalError from "./internalError";

export const DISCOURSE_GRAPH_PROP_NAME = "discourse-graph";
export const TENTATIVE_PROP_KEY = "tentative";
export const IMPORTED_FROM_PROP_KEY = "importedFrom";

// Annotations describe a relation's review/provenance state; they are not part
// of its identity, so lookups by role parameters must ignore them.
const RELATION_ANNOTATION_KEYS = new Set<string>([
  TENTATIVE_PROP_KEY,
  IMPORTED_FROM_PROP_KEY,
]);

const countRoleKeys = (params: Record<string, unknown>): number =>
  Object.keys(params).filter((k) => !RELATION_ANNOTATION_KEYS.has(k)).length;

const SANE_ROLE_NAME_RE = new RegExp(/^[\w-]*$/);

export const strictQueryForReifiedBlocks = async (
  parameterUids: Record<string, string>,
  { acceptedOnly = false }: { acceptedOnly?: boolean } = {},
): Promise<string | null> => {
  const paramsAsSeq = Object.entries(parameterUids);
  // validate parameter names
  if (
    Object.keys(parameterUids).filter((k) => !k.match(SANE_ROLE_NAME_RE)).length
  )
    throw new Error(
      `invalid parameter names in ${Object.keys(parameterUids).join(", ")}`,
    );
  const query = `[:find ?u ?d
  :in $ ${paramsAsSeq.map(([k]) => "?" + k).join(" ")}
  :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :${DISCOURSE_GRAPH_PROP_NAME}) ?d]
  ${paramsAsSeq.map(([k]) => `[(get ?d :${k}) ?${k}]`).join(" ")} ]`;
  const result = (await window.roamAlphaAPI.data.async.q(
    query,
    ...paramsAsSeq.map(([, v]) => v),
  )) as [string, Record<string, string>][];
  // post-filtering because cannot filter by number of keys in datascript
  const numParams = countRoleKeys(parameterUids);
  const resultF = result
    .filter(
      ([, params]) =>
        countRoleKeys(params) === numParams &&
        (!acceptedOnly || params[TENTATIVE_PROP_KEY] !== "true"),
    )
    .map(([uid]) => uid);
  if (resultF.length > 1) {
    const paramsAsText = Object.entries(parameterUids)
      .map(([k, v]) => `${k}: '${v}'`)
      .join(", ");
    console.warn(
      `${resultF.length} results in strict query for {${paramsAsText}}`,
    );
  }
  return resultF.length > 0 ? resultF[0] : null;
};

export const acceptTentativeRelationInstance = async ({
  instanceUid,
}: {
  instanceUid: string;
}): Promise<void> => {
  const existing = getBlockProps(instanceUid)[DISCOURSE_GRAPH_PROP_NAME];
  if (!isJsonObject(existing) || typeof existing.sourceUid !== "string") {
    throw new Error(
      "The relation block could not be read. It may have been deleted; refresh and try again.",
    );
  }
  if (existing[TENTATIVE_PROP_KEY] === undefined) return;
  const accepted = { ...existing };
  delete accepted[TENTATIVE_PROP_KEY];
  await setBlockPropsAsync(instanceUid, {
    [DISCOURSE_GRAPH_PROP_NAME]: accepted,
  });
};

const createReifiedBlock = async ({
  destinationBlockUid,
  schemaUid,
  parameterUids,
}: {
  destinationBlockUid: string;
  schemaUid: string;
  parameterUids: Record<string, string>;
}): Promise<string> => {
  // TODO: Check that the parameterUids keys correspond to the schema
  const data = {
    ...parameterUids,
    hasSchema: schemaUid,
  };
  const existing = await strictQueryForReifiedBlocks(data);
  if (existing !== null) {
    // Deliberate local creation counts as user acceptance, so a dedupe hit on
    // a tentative imported block promotes it instead of returning a block the
    // UI hides as pending review. Best-effort: the relation exists either way.
    if (parameterUids[TENTATIVE_PROP_KEY] === undefined) {
      try {
        await acceptTentativeRelationInstance({ instanceUid: existing });
      } catch (error) {
        internalError({
          error,
          type: "Promote Tentative Relation On Create Failed",
          context: { instanceUid: existing },
          sendEmail: false,
        });
      }
    }
    return existing;
  }
  const newUid = window.roamAlphaAPI.util.generateUID();
  await createBlock({
    node: {
      text: newUid,
      uid: newUid,
      props: {
        [DISCOURSE_GRAPH_PROP_NAME]: data,
      },
    },
    parentUid: destinationBlockUid,
    order: "last",
  });
  return newUid;
};

const RELATION_PAGE_TITLE = "roam/js/discourse-graph/relations";
let relationPageUid: string | undefined = undefined;

const getOrCreateRelationPageUid = async (): Promise<string> => {
  if (relationPageUid === undefined) {
    relationPageUid = getPageUidByPageTitle(RELATION_PAGE_TITLE);
    if (relationPageUid === "") {
      relationPageUid = await createPage({ title: RELATION_PAGE_TITLE });
    }
  }
  return relationPageUid;
};

export const getExistingRelationPageUid = (): string | undefined => {
  if (relationPageUid === undefined) {
    const uid = getPageUidByPageTitle(RELATION_PAGE_TITLE);
    if (uid !== "") relationPageUid = uid;
  }
  return relationPageUid;
};

export const countReifiedRelations = async (): Promise<number> => {
  const pageUid = getExistingRelationPageUid();
  if (pageUid === undefined) return 0;
  const r = await window.roamAlphaAPI.data.async.q(
    `[:find (count ?c) :where [?p :block/children ?c] [?p :block/uid "${pageUid}"]]`,
  );
  return (r[0] || [0])[0] as number;
};

export type ReifiedRelationData = {
  sourceUid: string;
  destinationUid: string;
  hasSchema: string;
  tentative?: string;
  importedFrom?: json;
  importedFromRid?: string;
};

export type ReifiedRelationDataWithRelId = ReifiedRelationData & {
  relationId: string;
};

export const getReifiedRelations = async (): Promise<
  ReifiedRelationDataWithRelId[]
> => {
  const pageUid = getExistingRelationPageUid();
  if (pageUid === undefined) return [];
  const r = await window.roamAlphaAPI.data.async.q(
    `[:find ?ruid ?rdata :where
      [?p :block/uid "${pageUid}"]
      [?p :block/children ?c]
      [?c :block/uid ?ruid]
      [?c :block/props ?pr]
      [(get ?pr :${DISCOURSE_GRAPH_PROP_NAME}) ?rdata] ]`,
  );
  return r.map((x) => ({
    relationId: x[0] as string,
    ...(x[1] as ReifiedRelationData),
  }));
};

export const createReifiedRelation = async ({
  sourceUid,
  relationBlockUid,
  destinationUid,
  tentative,
}: {
  sourceUid: string;
  relationBlockUid: string;
  destinationUid: string;
  tentative?: boolean;
}): Promise<string> => {
  const parameterUids: Record<string, string> = {
    sourceUid,
    destinationUid,
    ...(tentative !== undefined && {
      [TENTATIVE_PROP_KEY]: String(tentative),
    }),
  };
  return await createReifiedBlock({
    destinationBlockUid: await getOrCreateRelationPageUid(),
    schemaUid: relationBlockUid,
    parameterUids,
  });
};
import type {
  InputTextNode,
  RoamBasicNode,
  TextNode,
} from "roamjs-components/types/native";
import getSettingValueFromTree from "roamjs-components/util/getSettingValueFromTree";
import toFlexRegex from "roamjs-components/util/toFlexRegex";
import DEFAULT_RELATION_VALUES from "~/data/defaultDiscourseRelations";
import {
  isNewSettingsStoreEnabled,
  getAllRelations,
  type SettingsSnapshot,
} from "~/components/settings/utils/accessors";
import discourseConfigRef from "./discourseConfigRef";
import { getStoredRelationsEnabled } from "~/utils/storedRelations";

export type Triple = readonly [string, string, string];
export type DiscourseRelation = {
  triples: Triple[];
  id: string;
  label: string;
  source: string;
  destination: string;
  complement: string;
};

const matchNodeText = (keyword: string) => {
  return (node: RoamBasicNode | TextNode) =>
    toFlexRegex(keyword).test(node.text);
};

export const getGrammarNode = () => {
  return discourseConfigRef.tree.find(matchNodeText("grammar"));
};

export const getRelationsNode = (grammarNode = getGrammarNode()) => {
  return grammarNode?.children.find(matchNodeText("relations"));
};

const getDiscourseRelations = (snapshot?: SettingsSnapshot) => {
  const newStoreEnabled = snapshot
    ? snapshot.featureFlags["Use new settings store"]
    : isNewSettingsStoreEnabled();
  if (newStoreEnabled) {
    return getAllRelations(snapshot);
  }

  const grammarNode = getGrammarNode();
  const relationsNode = getRelationsNode(grammarNode);
  const relationNodes = relationsNode?.children || DEFAULT_RELATION_VALUES;
  const storedRelationsEnabled = getStoredRelationsEnabled();
  const discourseRelations = relationNodes.flatMap(
    (r: InputTextNode, i: number) => {
      const tree = (r?.children || []) as TextNode[];
      const data = {
        id: r.uid || `${r.text}-${i}`,
        label: r.text,
        source: getSettingValueFromTree({ tree, key: "Source" }),
        destination: getSettingValueFromTree({ tree, key: "Destination" }),
        complement: getSettingValueFromTree({ tree, key: "Complement" }),
      };
      const ifNode = tree.find(matchNodeText("if"))?.children || [];
      if (ifNode.length === 0 && storedRelationsEnabled) {
        return [{ ...data, triples: [] }];
      }
      return ifNode.map((node) => ({
        ...data,
        triples: node.children
          .filter((t) => !/node positions/i.test(t.text))
          .map((t) => {
            const target = t.children[0]?.children?.[0]?.text || "";
            return [t.text, t.children[0]?.text, target] as const;
          }),
      }));
    },
  );

  return discourseRelations;
};

export default getDiscourseRelations;
import {
  isRelationSchemaDeleted,
  notifyRelationSchemaChange,
} from "./relationSchemaChanges";
import { DISCOURSE_GRAPH_PROP_NAME } from "./createReifiedBlock";
import getBlockProps, { isJsonObject } from "./getBlockProps";
import { setBlockPropsAsync } from "./setBlockProps";
import {
  parseImportedSourceIdentity,
  type ImportedSourceIdentity,
} from "./importedSourceIdentity";

type ImportStatus = "provisional" | "accepted";

export const RELATION_SCHEMA_STATUS_PROP_KEY = "status";
const ACCEPTED_STATUS: ImportStatus = "accepted";

export type RelationSchemaImportMeta = {
  importedFrom: ImportedSourceIdentity;
  status: ImportStatus;
};

// Origin (importedFrom) and acceptance (status) are stored as separate props so
// accepting never erases provenance; a schema with origin but no accepted
// status is provisional, which also covers schemas imported before acceptance
// existed.
export const readRelationSchemaImportMeta = (
  relationSchemaUid: string,
): RelationSchemaImportMeta | undefined => {
  const props = getBlockProps(relationSchemaUid);
  const importedFrom = parseImportedSourceIdentity(props);
  if (importedFrom === undefined) return undefined;
  const discourseGraphProps = props[DISCOURSE_GRAPH_PROP_NAME];
  const status =
    isJsonObject(discourseGraphProps) &&
    discourseGraphProps[RELATION_SCHEMA_STATUS_PROP_KEY] === ACCEPTED_STATUS
      ? ACCEPTED_STATUS
      : "provisional";
  return { importedFrom, status };
};

export const isProvisionalRelationSchema = (
  relationSchemaUid: string,
): boolean =>
  readRelationSchemaImportMeta(relationSchemaUid)?.status === "provisional";

export const isAcceptedRelationSchema = (relation: { id: string }): boolean =>
  !isRelationSchemaDeleted(relation.id) &&
  !isProvisionalRelationSchema(relation.id);

export const excludeProvisionalRelationSchemas = <T extends { id: string }>(
  relations: T[],
): T[] => relations.filter(isAcceptedRelationSchema);

export const acceptImportedRelationSchema = async (
  relationSchemaUid: string,
): Promise<void> => {
  const existing = getBlockProps(relationSchemaUid)[DISCOURSE_GRAPH_PROP_NAME];
  const discourseGraphProps = isJsonObject(existing) ? existing : {};
  await setBlockPropsAsync(relationSchemaUid, {
    [DISCOURSE_GRAPH_PROP_NAME]: {
      ...discourseGraphProps,
      [RELATION_SCHEMA_STATUS_PROP_KEY]: ACCEPTED_STATUS,
    },
  });
  notifyRelationSchemaChange();
};

