    reason?: string;
    nextUpdateTime?: Date;
    lastUpdateTime?: Date;
    endSyncResult?: EndSyncTaskRpcResult;
  }): Properties =>
    syncTelemetryContext({
      attemptId,
      worker,
      userUid,
      syncFunction,
      context,
