          supabaseClient: activeSupabaseClient,
          context: activeContext,
        }),
    });
    if (schemaFormatBackfill !== null) {
      reportSchemaFormatBackfill({
        backfilled: schemaFormatBackfill.nodeTypeIdsToBackfill.size,
        skipped: schemaFormatBackfill.withFormatCount,
        orphaned: schemaFormatBackfill.orphanedCount,
      });
    }
    if (coreTitleBackfill !== null) {
      reportCoreTitleBackfill({
        backfilled: nodesToBackfillCoreTitle.length,
        deferred:
          coreTitleBackfill.nodesToBackfill.length -
          nodesToBackfillCoreTitle.length,
        skipped: coreTitleBackfill.withCoreTitleCount,
        orphaned: coreTitleBackfill.orphanedCount,
      });
    }
    await measureSyncPhase({
      phase: "cleanupOrphanedNodes",
      phases,
      operation: () =>
        cleanupOrphanedNodes(activeSupabaseClient, activeContext),
    });
    const completeEndResult = await measureSyncPhase({
      phase: "endSyncTask",
      phases,
      operation: () =>
        endSyncTask({
          worker,
          syncFunction,
          status: "complete",
          showToast,
          taskStartedAt: activeClaimedAt,
          context: activeContext,
          supabaseClient: activeSupabaseClient,
          telemetryContext: buildTelemetry({
            status: "complete",
            lastUpdateTime,
          }),
        }),
    });

    if (completeEndResult.ok) {
      initialSync = false;
      posthog.capture(
        "Sync complete",
        buildTelemetry({
          status: "complete",
          lastUpdateTime,
          endSyncResult: completeEndResult.rpcResult,
        }),
      );
    } else if (completeEndResult.stale) {
      posthog.capture(
        "Sync stale",
        buildTelemetry({
          status: "stale",
          reason:
            completeEndResult.rpcResult?.reason ||
            "end_sync_task completed by newer sync task",
          lastUpdateTime,
          endSyncResult: completeEndResult.rpcResult,
        }),
      );
    } else {
      posthog.capture(
        "Sync error",
        buildTelemetry({
          status: "end_task_failed",
          reason: completeEndResult.error.message,
          lastUpdateTime,
          endSyncResult: completeEndResult.rpcResult,
        }),
      );
    }
  } catch (error) {
    console.error("createOrUpdateDiscourseEmbedding: Process failed:", error);
    success = false;
    const reason =
      failureReason ??
      (error instanceof Error ? error.message : "Unknown sync error");
    const capturedError =
      error instanceof Error ? error : new Error(reason, { cause: error });
    const syncErrorContext =
      failureContext ??
      (typeof error === "object" && error !== null
        ? getSupabaseErrorTelemetry({ error, prefix: "syncError" })
        : {});
    let failedEndResult: EndSyncTaskResult | undefined;
    const failedClaimedAt = claimedAt;
    if (failedClaimedAt !== null) {
      failedEndResult = await measureSyncPhase({
        phase: "endSyncTaskFailed",
        phases,
        operation: () =>
          endSyncTask({
            worker,
            syncFunction,
            status: "failed",
            showToast,
            taskStartedAt: failedClaimedAt,
            context: context || undefined,
            supabaseClient: supabaseClient || undefined,
            telemetryContext: buildTelemetry({ status: "failed", reason }),
          }),
      });
    }
    const isFatal = failureReason === undefined && error instanceof FatalError;
    const status = isFatal ? "fatal" : "failed";
    const errorTelemetry = buildTelemetry({
      status,
      reason,
      endSyncResult: failedEndResult?.rpcResult,
    });
    internalError({
      error: capturedError,
      type: "Sync Failed",
      context: {
        ...errorTelemetry,
        ...syncErrorContext,
      },
    });
    posthog.capture("Sync error", errorTelemetry);
    if (isFatal) {
      doSync = false;
      return;
    }
  }
  let timeout = BASE_SYNC_INTERVAL;
  if (success) {
    numFailures = 0;
  } else {
    numFailures += 1;
    if (numFailures >= MAX_FAILURES) {
      doSync = false;
      return;
    }
    const jitter = 0.9 + Math.random() * 0.2; // 0.9x-1.1x
    timeout *= 2 ** numFailures * jitter;
  }
  if (activeTimeout != null) {
    clearTimeout(activeTimeout);
    activeTimeout = null;
  }
  if (doSync) {
    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    activeTimeout = setTimeout(createOrUpdateDiscourseEmbedding, timeout);
  }
};

export const initializeSupabaseSync = (): void => {
  if (activeTimeout !== null) {
    clearTimeout(activeTimeout);
    activeTimeout = null;
  }

  doSync = true;
  // eslint-disable-next-line @typescript-eslint/no-misused-promises
  activeTimeout = setTimeout(createOrUpdateDiscourseEmbedding, 100, true);
};
