        });
        return queryResults.map((result) => ({ ...result, type: d.type }));
      }),
    );

    exportRender({
      results: results.flat(),
      title: "Export Discourse Graph",
      isExportDiscourseGraph: true,
    useState<(typeof SEND_TO_DESTINATIONS)[number]>("page");
  const isSendToGraph = activeSendToDestination === "graph";
  const [livePages, setLivePages] = useState<Result[]>([]);
  const sharingEnabled = useMemo(() => isNodeSharingEnabled(), []);
  const [selectedTabId, setSelectedTabId] = useState("sendto");
  useEffect(() => {
    if (initialPanel === "publish" && !sharingEnabled) return;
    if (initialPanel) setSelectedTabId(INITIAL_PANEL_TO_TAB_ID[initialPanel]);
  }, [initialPanel, sharingEnabled]);
  const [includeDiscourseContext, setIncludeDiscourseContext] = useState(false);
  const [gitHubAccessToken, setGitHubAccessToken] = useState<string | null>(
    getSetting<string | null>("oauth-github", null),
  );

  const [canSendToGitHub, setCanSendToGitHub] = useState(false);

  const [myGroups, setMyGroups] = useState<MyGroup[]>([]);
  const [groupsLoading, setGroupsLoading] = useState(false);
  const [groupsLoaded, setGroupsLoaded] = useState(false);
  const [selectedGroupIds, setSelectedGroupIds] = useState<string[]>([]);
  const [groupsError, setGroupsError] = useState("");
  const [publishError, setPublishError] = useState("");

  const publishableNodes = useMemo(
    () =>
      sharingEnabled
        ? results
            .map((r) => {
              const node = findDiscourseNode({ uid: r.uid });
              return node && node.backedBy === "user"
                ? { uid: r.uid, type: node.type }
                : null;
            })
            .filter((n): n is NodeUidWithType => n !== null)
        : [],
    [results, sharingEnabled],
  );
  const nonDiscourseCount = results.length - publishableNodes.length;

  const writeFileToRepo = async ({
    filename,
    content,
    setError,
  }: {
    filename: string;
    content: string;
    setError: (error: string) => void;
  }): Promise<{ status: number }> => {
    const base64Content = btoa(content);

    try {
      const response = await apiPut({
        domain: "https://api.github.com",
        path: `repos/${selectedRepo}/contents/${filename}`,
        headers: { Authorization: `token ${gitHubAccessToken}` },
        data: { message: `Add ${filename}`, content: base64Content },
  };
  cleanups: Array<() => void>;
} => {
  const pageTitleObserver = createHTMLObserver({
    tag: "H1",
    className: "rm-title-display",
    callback: (e) => {
      const h1 = e as HTMLHeadingElement;
      const { title, uid } = getTitleAndUidFromHeader(h1);

      const settings = bulkReadSettings();

      const props = { title, h1, onloadArgs };

      const node = findDiscourseNode({
        uid,
        title,
        snapshot: settings,
      });

      const sharingEnabled =
        settings.featureFlags[FEATURE_FLAG_KEYS.enableNodeSharing];
      const isImportedNode =
        sharingEnabled && Boolean(uid && readImportedSourceIdentity(uid));
      if (isImportedNode) {
        renderRefreshImportedNodeTitleButton({ h1, uid });
      }
      const isDiscourseNode = node && node.backedBy !== "default";
      if (isDiscourseNode) {
        if (sharingEnabled && node.backedBy === "user" && !isImportedNode) {
          renderPublishNodeTitleButton({
            h1,
            uid,
            title,
            nodeType: node.type,
          });
        }
        renderDiscourseContext({ h1, uid });
        const linkedReferencesDiv = document.querySelector(
          ".rm-reference-main",
        ) as HTMLDivElement;
      const notice = new DocumentFragment();
      const wrapper = createSpan({
        text: "Destination file already exists at ",
      });
      const linkEl = createEl("a");
      linkEl.textContent = destinationFile.path;
      linkEl.classList.add("dg-clickable-link");
      wrapper.appendChild(linkEl);
      notice.appendChild(wrapper);
      linkEl.addEventListener("click", () => {
        void plugin.app.workspace.openLinkText(destinationFile.path, "", false);
      });

      new Notice(notice, 5000);
      return;
    }

    if (file.path !== newPath) {
      if (folderPath) {
        const folderExists = plugin.app.vault.getAbstractFileByPath(folderPath);
        if (!folderExists) {
          await plugin.app.vault.createFolder(folderPath);
        }
      }
      await plugin.app.fileManager.renameFile(file, newPath);
    }

    await plugin.app.fileManager.processFrontMatter(
      file,
      (fm: Record<string, unknown>) => {
        fm.nodeTypeId = nodeType.id;
      },
    );

    new Notice("Converted page to discourse node", 10000);
  } catch (error) {
    console.error("Error converting to discourse node:", error);
    new Notice(
      `Error converting to discourse node: ${error instanceof Error ? error.message : String(error)}`,
      5000,
    );
  }
};
  groups.map((group) => ({
    ...group,
    isPublished: publishedToGroups.includes(group.id),
  }));

export const publishNodeToSelectedGroup = async ({
  plugin,
  file,
  frontmatter,
  groupId,
}: {
  plugin: DiscourseGraphPlugin;
  file: TFile;
  frontmatter: FrontMatterCache | Record<string, unknown>;
  groupId: string;
}): Promise<void> => {
  const publishedToGroups = getPublishedToGroups(frontmatter);
  if (publishedToGroups.includes(groupId)) {
    throw new Error("Already shared with this group");
  }

  if (!frontmatter.nodeInstanceId) {
    throw new Error("Please sync the node first");
  }

  await publishNode({
    plugin,
    file,
    frontmatter: frontmatter as FrontMatterCache,
    groupId,
  });
};

