import { afterEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  getLoggedInClient: vi.fn(),
  internalError: vi.fn(),
  posthogCapture: vi.fn(),
}));

vi.mock("~/utils/getDiscourseNodes", () => ({ default: () => [] }));
vi.mock("~/utils/internalError", () => ({ default: mocks.internalError }));
vi.mock("~/utils/supabaseContext", () => ({
  getLoggedInClient: mocks.getLoggedInClient,
  getSupabaseContext: vi.fn(),
}));
vi.mock("~/components/settings/utils/accessors", () => ({
  isSyncEnabled: () => false,
}));
vi.mock("posthog-js", () => ({
  default: { capture: mocks.posthogCapture },
}));

import { initializeSupabaseSync } from "~/utils/syncDgNodesToSupabase";

afterEach(() => {
  vi.clearAllTimers();
  vi.useRealTimers();
  vi.unstubAllGlobals();
  vi.clearAllMocks();
});

describe("createOrUpdateDiscourseEmbedding failure cutoff", () => {
  it("stops scheduling after five failed attempts in one loaded module", async () => {
    vi.useFakeTimers();
    vi.stubGlobal("window", {
      roamAlphaAPI: { user: { uid: () => "test-user" } },
    });
    mocks.getLoggedInClient.mockResolvedValue(null);

    initializeSupabaseSync();

    for (let attempt = 0; attempt < 5; attempt++) {
      await vi.advanceTimersToNextTimerAsync();
      expect(mocks.getLoggedInClient).toHaveBeenCalledTimes(attempt + 1);
    }

    expect(vi.getTimerCount()).toBe(0);
    expect(mocks.internalError).toHaveBeenCalledTimes(5);
  });
});

