            />
          </Tooltip>
        </div>

        {importProgress ? (
          <Callout
            title={`Importing ${importProgress.current} of ${importProgress.total}…`}
          >
            <ProgressBar
              intent={Intent.PRIMARY}
              value={importProgress.current / importProgress.total}
            />
          </Callout>
        ) : (
