// @vitest-environment jsdom
import React from "react";
import { createRoot, type Root } from "react-dom/client";
import { act } from "react-dom/test-utils";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { DiscoverSharedNodesDialog } from "~/components/DiscoverSharedNodesDialog";

const mocks = vi.hoisted(() => ({
  discoverSharedNodes: vi.fn(),
  getLoggedInClient: vi.fn(),
  getSupabaseContext: vi.fn(),
  importSharedNodes: vi.fn(),
  importSharedRelations: vi.fn(),
  resolveRelations: (() => undefined) as () => void,
}));

vi.mock("~/utils/discoverSharedNodes", () => ({
  discoverSharedNodes: mocks.discoverSharedNodes,
}));
vi.mock("~/utils/importSharedNodes", () => ({
  importSharedNodes: mocks.importSharedNodes,
  isFailedSharedNodeImport: (item: { status: string }) =>
    item.status === "failed",
}));
vi.mock("~/utils/importSharedRelations", () => ({
  importSharedRelations: mocks.importSharedRelations,
}));
vi.mock("~/utils/supabaseContext", () => ({
  getLoggedInClient: mocks.getLoggedInClient,
  getSupabaseContext: mocks.getSupabaseContext,
}));
vi.mock("~/utils/internalError", () => ({ default: vi.fn() }));
vi.mock("roamjs-components/queries/getPageTitleByPageUid", () => ({
  default: (uid: string) => uid,
}));
vi.mock("roamjs-components/util/createOverlayRender", () => ({
  default: <T,>(_id: string, Component: T) => Component,
}));
vi.mock("roamjs-components/writes/openBlockInSidebar", () => ({
  default: vi.fn(),
}));

let container: HTMLDivElement;
let root: Root;

const node = {
  rid: "orn:roam.node:source-space/node-1",
  spaceName: "Source space",
  spaceUri: "roam:source-space",
  title: "Imported evidence",
  lastModified: "2026-09-25T00:00:00.000Z",
} as never;

const flush = async (): Promise<void> => {
  await act(async () => {
    await Promise.resolve();
    await Promise.resolve();
  });
};

beforeEach(() => {
  Object.assign(globalThis, { IS_REACT_ACT_ENVIRONMENT: true });
  mocks.getSupabaseContext.mockResolvedValue({ spaceId: 12 });
  mocks.getLoggedInClient.mockResolvedValue({});
  mocks.discoverSharedNodes.mockResolvedValue({
    sharedNodes: [node],
    importedSourceRids: new Set(),
  });
  mocks.importSharedNodes.mockImplementation(
    async ({ onProgress }: { onProgress: (current: number, total: number) => void }) => {
      onProgress(1, 1);
      return [{ sharedNode: node, status: "imported", pageUid: "imported-page" }];
    },
  );
  mocks.importSharedRelations.mockImplementation(
    () =>
      new Promise<void>((resolve) => {
        mocks.resolveRelations = resolve;
      }),
  );
  container = document.createElement("div");
  document.body.appendChild(container);
  root = createRoot(container);
});

afterEach(() => {
  act(() => root.unmount());
  container.remove();
  vi.clearAllMocks();
});

describe("DiscoverSharedNodesDialog import progress", () => {
  it("keeps results hidden and the dialog disabled until the relation stage resolves", async () => {
    await act(async () => {
      root.render(React.createElement(DiscoverSharedNodesDialog, { onClose: vi.fn() }));
      await Promise.resolve();
    });
    await flush();

    const checkbox = container.querySelector(
      '[aria-label="Select Imported evidence"]',
    ) as HTMLInputElement;
    expect(checkbox).toBeTruthy();
    await act(async () => checkbox.click());
    const importButton = [...container.querySelectorAll("button")].find((button) =>
      button.textContent?.includes("Import selected (1)"),
    );
    expect(importButton).toBeTruthy();

    await act(async () => importButton?.click());
    await flush();

    expect(container.textContent).toContain("Importing 1 of 1…");
    expect(container.textContent).not.toContain("1 imported, 0 skipped, 0 failed");
    expect(
      [...container.querySelectorAll("button")].find(
        (button) => button.textContent === "Close",
      )?.disabled,
    ).toBe(true);

    await act(async () => mocks.resolveRelations());
    await flush();

    expect(container.textContent).toContain("1 imported, 0 skipped, 0 failed");
    expect(
      [...container.querySelectorAll("button")].find(
        (button) => button.textContent === "Close",
      )?.disabled,
    ).toBe(false);
  });
});

