import { describe, expect, it } from "vitest";
import {
  orderConceptsByDependency,
  relationInstanceToLocalConcept,
} from "~/utils/conceptConversion";

describe("relationInstanceToLocalConcept", () => {
  it("converts bare local endpoint IDs when the vault map contains both nodes", () => {
    const relation = relationInstanceToLocalConcept({
      context: { spaceId: 12, userId: "author" } as never,
      relationTypesById: { supports: { label: "supports" } as never },
      allNodesById: {
        source: {
          file: { basename: "Source" },
          frontmatter: {},
        } as never,
        destination: {
          file: { basename: "Destination" },
          frontmatter: {},
        } as never,
      },
      relationInstanceData: {
        id: "relation-id",
        type: "supports",
        source: "source",
        destination: "destination",
        created: 1_758_800_000_000,
      } as never,
    });

    expect(relation).toMatchObject({
      source_local_id: "relation-id",
      schema_represented_by_local_id: "supports",
      local_reference_content: { source: "source", destination: "destination" },
    });
    expect(orderConceptsByDependency([relation!])).toMatchObject({
      ordered: [expect.objectContaining({ source_local_id: "relation-id" })],
      missing: ["source", "destination", "supports"],
    });
  });
});

