  ]);
  for (const [index, response] of residue.entries()) {
    if (response.error)
      errors.push(`verify cleanup ${index}: ${String(response.error)}`);
  }
  const userResidue = await Promise.all(
    userIds.map(async (userId) => {
      const response = await service.auth.admin.getUserById(userId);
      return { error: response.error, exists: response.data.user !== null };
