const runSec01 = async ({
  service,
  target,
  runId,
}: {
  service: Client;
  target: string;
  runId: string;
}): Promise<RunRecord> => {
  const users: RunUser[] = [];
  const spaces: number[] = [];
  const platformAccounts: PlatformAccount[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  let executionError: string | null = null;
  try {
    await Promise.all(
      ["owner", "member", "outsider", "control-candidate"].map(async (role) =>
        users.push(await createUser({ service, runId, role })),
      ),
    );
    const owner = getRunUser({ role: "owner", users });
    const member = getRunUser({ role: "member", users });
    const outsider = getRunUser({ role: "outsider", users });
    const controlCandidate = getRunUser({ role: "control-candidate", users });
    const spaceId = await createSpace({
      service,
      runId,
      suffix: "sec01-target",
    });
    spaces.push(spaceId);
    const sec01Roles = [
      "owner",
      "member",
      "outsider",
      "control-candidate",
    ] as const;
    platformAccounts.push(
      ...(await Promise.all(
        [owner, member, outsider, controlCandidate].map(async (user, index) =>
          createPlatformAccount({
            service,
            userId: user.id,
            runId,
            role: sec01Roles[index]!,
          }),
        ),
      )),
    );
    await Promise.all([
      grantSpaceAccess({ service, accountId: owner.id, spaceId }),
      grantSpaceAccess({ service, accountId: member.id, spaceId }),
    ]);
    const outsiderClient = await signIn({ email: outsider.email, target });
    const before = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    assert.equal(
      before,
      null,
      "outsider unexpectedly had target-space access before the attempt",
    );
    const outsiderVisibilityBefore = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId,
    });
    const outsiderAttempt = await outsiderClient.rpc(
      "upsert_account_in_space",
      {
        local_account: {
          account_local_id: platformAccounts[2]!.localId,
          email: null,
          email_trusted: null,
          name: `${runId} outsider`,
          permissions: "editor",
          permissions: "editor",
          space_editor: null,
        },
        space_id_: spaceId,
      },
    );
    const after = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    const outsiderVisibilityAfter = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId,
    });
    const outsiderWriteAfter = await writeOrdinarySpaceAccess({
      client: outsiderClient,
      runId,
      spaceId,
    });
    const memberClient = await signIn({ email: member.email, target });
    const permittedControl = await memberClient.rpc("upsert_account_in_space", {
      local_account: {
        account_local_id: platformAccounts[3]!.localId,
        email: null,
        email_trusted: null,
        name: `${runId} control candidate`,
        permissions: "editor",
        space_editor: null,
      },
      space_id_: spaceId,
    });
    const permittedGrant = await getSpaceGrant({
      service,
      accountId: controlCandidate.id,
      spaceId,
    });
    assert.equal(
      permittedControl.error,
      null,
      "permitted member control could not grant access",
    );
    assert.notEqual(
      permittedGrant,
      null,
      "permitted member control did not persist",
    );
    observation = {
      fixtures: {
        spaceIds: spaces,
        users: users.map(({ id, role }) => ({ id, role })),
        platformAccountIds: platformAccounts.map(({ id }) => id),
      },
      outsiderBefore: {
        grant: before,
        ordinarySpaceRead: outsiderVisibilityBefore,
      },
      outsiderAttempt: {
        error: getErrorMessage(outsiderAttempt.error),
        returnedAccountId: outsiderAttempt.data ?? null,
      },
      outsiderGrantAfter: after,
      outsiderOrdinaryAccessAfter: {
        read: outsiderVisibilityAfter,
        write: outsiderWriteAfter,
      },
      permittedMemberControl: {
        error: getErrorMessage(permittedControl.error),
        grant: permittedGrant,
      },
      hypothesisReproduced:
        outsiderAttempt.error === null &&
        after !== null &&
        outsiderVisibilityAfter.visible &&
        outsiderWriteAfter.wrote,
    };
  } catch (error) {
    executionError = error instanceof Error ? error.message : String(error);
    observation = {
      ...observation,
      fixtures: {
        spaceIds: spaces,
        users: users.map(({ id, role }) => ({ id, role })),
        platformAccountIds: platformAccounts.map(({ id }) => id),
      },
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds: [],
      platformAccountIds: platformAccounts.map(({ id }) => id),
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return {
    candidate: CANDIDATE,
    caseId: "SEC-01",
    cleanup,
    createdAt: new Date().toISOString(),
    executionError,
    fixtures: {
      groupIds: [],
      platformAccountIds: platformAccounts.map(({ id }) => id),
      spaceIds: spaces,
      users: users.map(({ id, role }) => ({ id, role })),
    },
    observation,
    runId,
    target,
  };
};

const runSec02 = async ({
  service,
  target,
  runId,
}: {
  service: Client;
  target: string;
  runId: string;
}): Promise<RunRecord> => {
  const users: RunUser[] = [];
  const spaces: number[] = [];
  const groupIds: string[] = [];
  const platformAccounts: PlatformAccount[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  let executionError: string | null = null;
  try {
    const roles = [
      "outsider",
      "protected-group",
      "positive-group",
      "positive-admin",
      "positive-member",
      "former-member",
      "rejoin-group",
    ];
    await Promise.all(
      roles.map(async (role) => {
        users.push(await createUser({ service, runId, role }));
      }),
    );
    const outsider = getRunUser({ role: "outsider", users });
    const protectedGroup = getRunUser({ role: "protected-group", users });
    const positiveGroup = getRunUser({ role: "positive-group", users });
    const positiveAdmin = getRunUser({ role: "positive-admin", users });
    const positiveMember = getRunUser({ role: "positive-member", users });
    const formerMember = getRunUser({ role: "former-member", users });
    const rejoinGroup = getRunUser({ role: "rejoin-group", users });
    platformAccounts.push(
      ...(await Promise.all(
        users.map((user) =>
          createPlatformAccount({
            service,
            userId: user.id,
            runId,
            role: user.role,
          }),
        ),
      )),
    );
    groupIds.push(protectedGroup.id, positiveGroup.id, rejoinGroup.id);
    const protectedSpaceId = await createSpace({
      service,
      runId,
      suffix: "sec02-protected",
    });
    spaces.push(protectedSpaceId);
    await grantSpaceAccess({
      service,
      accountId: protectedGroup.id,
      spaceId: protectedSpaceId,
    });
    const outsiderClient = await signIn({ email: outsider.email, target });
    const outsiderMembershipBefore = await getMembership({
      service,
      groupId: protectedGroup.id,
      memberId: outsider.id,
    });
    const outsiderVisibilityBefore = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId: protectedSpaceId,
    });
    const freshAttempt = await outsiderClient.from("group_membership").insert({
      admin: false,
      group_id: protectedGroup.id,
      member_id: outsider.id,
    });
    const persistedFreshMembership = await getMembership({
      service,
      groupId: protectedGroup.id,
      memberId: outsider.id,
    });
    const inheritedSpaceRead = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId: protectedSpaceId,
    });
    const inheritedSpaceWrite = await writeOrdinarySpaceAccess({
      client: outsiderClient,
      runId,
      spaceId: protectedSpaceId,
    });
    const seedAdmin = await service.from("group_membership").insert({
      admin: true,
