      service.from("PlatformAccount").delete().in("dg_account", userIds),
    );
    for (const userId of userIds) {
      await remove(`delete auth user ${userId}`, async () =>
        service.auth.admin.deleteUser(userId),
      );
    }
  }
  const residue = await Promise.all([
    ...(spaceIds.length
      ? [
          service
            .from("Space")
            .select("id", { count: "exact", head: true })
            .in("id", spaceIds),
        ]
      : []),
    ...(groupIds.length
      ? [
          service
            .from("group_membership")
            .select("group_id", { count: "exact", head: true })
            .in("group_id", groupIds),
        ]
      : []),
    ...(userIds.length
      ? [
          service
            .from("group_membership")
            .select("member_id", { count: "exact", head: true })
            .in("member_id", userIds),
          service
            .from("PlatformAccount")
            .select("id", { count: "exact", head: true })
            .in("dg_account", userIds),
        ]
      : []),
    ...(platformAccountIds.length
      ? [
          service
            .from("LocalAccess")
            .select("account_id", { count: "exact", head: true })
            .in("account_id", platformAccountIds),
        ]
      : []),
    ...(spaceIds.length
      ? [
          service
            .from("SpaceAccess")
            .select("space_id", { count: "exact", head: true })
            .in("space_id", spaceIds),
          service
            .from("LocalAccess")
            .select("space_id", { count: "exact", head: true })
            .in("space_id", spaceIds),
        ]
      : []),
  ]);
  for (const [index, response] of residue.entries()) {
    if (response.error)
      errors.push(`verify cleanup ${index}: ${String(response.error)}`);
  }
  const userResidue = await Promise.all(
    userIds.map(async (userId) => {
      const response = await service.auth.admin.getUserById(userId);
      return { error: response.error, exists: response.data.user !== null };
    }),
  );
  for (const [index, response] of userResidue.entries()) {
    if (response.error && !/not found/i.test(response.error.message)) {
      errors.push(
        `verify deleted auth user ${index}: ${response.error.message}`,
      );
    }
    if (response.exists) errors.push(`fixture auth user ${index} remains`);
  }
  const verified =
    errors.length === 0 &&
    residue.every((response) => response.count === 0) &&
    userResidue.every((response) => !response.exists);
  return { errors, verified };
};

const runSec01 = async ({
  service,
  target,
  runId,
}: {
  service: Client;
  target: string;
  runId: string;
}): Promise<RunRecord> => {
  const users: RunUser[] = [];
  const spaces: number[] = [];
  const platformAccounts: PlatformAccount[] = [];
  const cleanup = { attempted: false, verified: false, errors: [] as string[] };
  let observation: Record<string, unknown> = {};
  let executionError: string | null = null;
  try {
    await Promise.all(
      ["owner", "member", "outsider", "control-candidate"].map(async (role) =>
        users.push(await createUser({ service, runId, role })),
      ),
    );
    const owner = getRunUser({ role: "owner", users });
    const member = getRunUser({ role: "member", users });
    const outsider = getRunUser({ role: "outsider", users });
    const controlCandidate = getRunUser({ role: "control-candidate", users });
    const spaceId = await createSpace({
      service,
      runId,
      suffix: "sec01-target",
    });
    spaces.push(spaceId);
    const sec01Roles = [
      "owner",
      "member",
      "outsider",
      "control-candidate",
    ] as const;
    platformAccounts.push(
      ...(await Promise.all(
        [owner, member, outsider, controlCandidate].map(async (user, index) =>
          createPlatformAccount({
            service,
            userId: user.id,
            runId,
            role: sec01Roles[index]!,
          }),
        ),
      )),
    );
    await Promise.all([
      grantSpaceAccess({ service, accountId: owner.id, spaceId }),
      grantSpaceAccess({ service, accountId: member.id, spaceId }),
    ]);
    const outsiderClient = await signIn({ email: outsider.email, target });
    const before = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    assert.equal(
      before,
      null,
      "outsider unexpectedly had target-space access before the attempt",
    );
    const outsiderVisibilityBefore = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId,
    });
    const outsiderAttempt = await outsiderClient.rpc(
      "upsert_account_in_space",
      {
        local_account: {
          account_local_id: platformAccounts[2]!.localId,
          email: null,
          email_trusted: null,
          name: `${runId} outsider`,
          permissions: "editor",
          permissions: "editor",
          space_editor: null,
        },
        space_id_: spaceId,
      },
    );
    const after = await getSpaceGrant({
      service,
      accountId: outsider.id,
      spaceId,
    });
    const outsiderVisibilityAfter = await readOrdinarySpaceAccess({
      client: outsiderClient,
      spaceId,
    });
    const outsiderWriteAfter = await writeOrdinarySpaceAccess({
      client: outsiderClient,
      runId,
      spaceId,
    });
    const memberClient = await signIn({ email: member.email, target });
    const permittedControl = await memberClient.rpc("upsert_account_in_space", {
      local_account: {
        account_local_id: platformAccounts[3]!.localId,
        email: null,
        email_trusted: null,
        name: `${runId} control candidate`,
        permissions: "editor",
        space_editor: null,
      },
      space_id_: spaceId,
    });
    const permittedGrant = await getSpaceGrant({
      service,
      accountId: controlCandidate.id,
      spaceId,
    });
    assert.equal(
      permittedControl.error,
      null,
      "permitted member control could not grant access",
    );
    assert.notEqual(
      permittedGrant,
      null,
      "permitted member control did not persist",
    );
    observation = {
      fixtures: {
        spaceIds: spaces,
        users: users.map(({ id, role }) => ({ id, role })),
        platformAccountIds: platformAccounts.map(({ id }) => id),
      },
      outsiderBefore: {
        grant: before,
        ordinarySpaceRead: outsiderVisibilityBefore,
      },
      outsiderAttempt: {
        error: getErrorMessage(outsiderAttempt.error),
        returnedAccountId: outsiderAttempt.data ?? null,
      },
      outsiderGrantAfter: after,
      outsiderOrdinaryAccessAfter: {
        read: outsiderVisibilityAfter,
        write: outsiderWriteAfter,
      },
      permittedMemberControl: {
        error: getErrorMessage(permittedControl.error),
        grant: permittedGrant,
      },
      hypothesisReproduced:
        outsiderAttempt.error === null &&
        after !== null &&
        outsiderVisibilityAfter.visible &&
        outsiderWriteAfter.wrote,
    };
  } catch (error) {
    executionError = error instanceof Error ? error.message : String(error);
    observation = {
      ...observation,
      fixtures: {
        spaceIds: spaces,
        users: users.map(({ id, role }) => ({ id, role })),
        platformAccountIds: platformAccounts.map(({ id }) => id),
      },
    };
  } finally {
    cleanup.attempted = true;
    const result = await cleanRun({
      groupIds: [],
      platformAccountIds: platformAccounts.map(({ id }) => id),
      service,
      spaceIds: spaces,
      userIds: users.map((user) => user.id),
    });
    cleanup.errors = result.errors;
    cleanup.verified = result.verified;
  }
  return {
    candidate: CANDIDATE,
    caseId: "SEC-01",
    cleanup,
    createdAt: new Date().toISOString(),
    executionError,
    fixtures: {
      groupIds: [],
      platformAccountIds: platformAccounts.map(({ id }) => id),
      spaceIds: spaces,
      users: users.map(({ id, role }) => ({ id, role })),
    },
    observation,
    runId,
    target,
  };
};

