    throw new Error(`create ${role} platform account returned no id`);
  return { id: response.data.id, localId };
};

const grantSpaceAccess = async ({
  accountId,
  service,
  spaceId,
}: {
  accountId: string;
  service: Client;
  spaceId: number;
}): Promise<void> => {
  const response = await service.from("SpaceAccess").insert({
    account_uid: accountId,
    permissions: "editor",
    space_id: spaceId,
  });
  assertNoError({
    error: response.error,
    context: "seed permitted space access",
  });
};

const getSpaceGrant = async ({
  accountId,
  service,
  spaceId,
}: {
  accountId: string;
  service: Client;
  spaceId: number;
}): Promise<unknown> => {
  const response = await service
    .from("SpaceAccess")
    .select("permissions")
    .eq("account_uid", accountId)
    .eq("space_id", spaceId)
