};

const readOrdinarySpaceAccess = async ({
  client,
  spaceId,
}: {
  client: Client;
  spaceId: number;
}): Promise<{ error: string | null; visible: boolean }> => {
  const response = await client
    .from("Space")
    .select("id")
    .eq("id", spaceId)
    .maybeSingle();
  return {
    error: getErrorMessage(response.error),
    visible: response.data !== null,
  };
};

