  clauses.flatMap((c) => {
    switch (c.type) {
      case "not-join-clause":
      case "or-join-clause":
      case "not-clause":
      case "or-clause":
      case "and-clause":
        return leafClauses(c.clauses);
      default:
        return [c];
    }
  });

const compile = (clauses: DatalogClause[]): string[] =>
  clauses.map((c) => compileDatalog(c, 0));

const clausesReadingTentative = (clauses: DatalogClause[]): string[] =>
  compile(leafClauses(clauses)).filter((c) =>
    c.includes(`:${TENTATIVE_PROP_KEY}`),
  );

const reldataKeysRead = (clauses: DatalogClause[]): string[] =>
  leafClauses(clauses).flatMap((c) =>
    c.type === "fn-expr" &&
    c.fn === "get" &&
    c.arguments[0]?.type === "variable" &&
    c.arguments[0].value.endsWith("reldata") &&
    c.arguments[1]?.type === "constant"
      ? [c.arguments[1].value]
      : [],
  );

const equalityConstantsFor = (
  clauses: DatalogClause[],
  variableSuffix: string,
): string[] =>
  leafClauses(clauses).flatMap((c) =>
    c.type === "pred-expr" &&
    c.pred === "=" &&
    c.arguments[0]?.type === "variable" &&
    c.arguments[0].value.endsWith(variableSuffix) &&
    c.arguments[1]?.type === "constant"
      ? [c.arguments[1].value]
      : [],
  );

const relationCondition = (target: string, relation: string): QBClause => ({
  type: "clause",
  uid: "rel-condition",
  source: "node",
  relation,
  target,
  not: false,
});

const cases = [
  {
    name: "node Supports Claim (node-type target)",
    condition: relationCondition("Claim", "Supports"),
    schemaConstrained: true,
    destinationConstrained: false,
  },
  {
    name: "node Supports <claim page uid> (specific-node target)",
    condition: relationCondition(CLAIM_UID, "Supports"),
    schemaConstrained: true,
    destinationConstrained: true,
  },
  {
    name: "node Has Any Relation To <claim page uid>",
    condition: relationCondition(CLAIM_UID, "Has Any Relation To"),
    schemaConstrained: false,
    destinationConstrained: true,
  },
];

describe("REL-11 pending relations in query results (Roam, stored relations on)", () => {
  it.each(cases)(
    "the generated query excludes pending instances: $name",
    async ({ name, condition, schemaConstrained, destinationConstrained }) => {
      const pending = await writePendingImportedInstance();
      const reldata = pending.props[DISCOURSE_GRAPH_PROP_NAME] as Record<
        string,
        string
      >;
      console.log(
        `ACTUAL [${name}] tentative prop key: "${TENTATIVE_PROP_KEY}"`,
      );
      console.log(
        `ACTUAL [${name}] pending block written under parent ${pending.parentUid} with props: ${JSON.stringify(pending.props)}`,
      );
      expect(TENTATIVE_PROP_KEY).toBe("tentative");
      expect(pending.parentUid).toBe(RELATION_PAGE_UID);
      expect(pending.props).toEqual({
        [DISCOURSE_GRAPH_PROP_NAME]: {
          sourceUid: EVIDENCE_UID,
          destinationUid: CLAIM_UID,
          [TENTATIVE_PROP_KEY]: "true",
          hasSchema: SUPPORTS_SCHEMA_UID,
        },
      });

      registerDiscourseDatalogTranslators();
      const clauses = conditionToDatalog(condition);
      const compiled = compile(clauses);
      const { query } = getDatalogQuery({
        returnNode: "node",
        conditions: [
          {
            type: "clause",
            uid: "isa-condition",
            source: "node",
            relation: "is a",
            target: "Evidence",
            not: false,
          },
          condition,
        ],
        selections: [],
      });
      const keysRead = reldataKeysRead(clauses);
      const tentativeReaders = clausesReadingTentative(clauses);
      const schemaConstants = equalityConstantsFor(clauses, "-relSchema");
      const targetConstants = equalityConstantsFor(clauses, "-relTarget");

      console.log(
        `ACTUAL [${name}] stored-relation translator clauses:\n${compiled.join("\n")}`,
      );
      console.log(`ACTUAL [${name}] full query builder query:\n${query}`);
      console.log(
        `ACTUAL [${name}] keys read from the stored relation's discourse-graph prop: ${JSON.stringify(keysRead)}`,
      );
      console.log(
        `ACTUAL [${name}] relSchema constraints: ${JSON.stringify(schemaConstants)}; relTarget constraints: ${JSON.stringify(targetConstants)}; pending block values: hasSchema="${reldata.hasSchema}", destinationUid="${reldata.destinationUid}"`,
      );
      console.log(
        `ACTUAL [${name}] clauses that read :${TENTATIVE_PROP_KEY}: ${JSON.stringify(tentativeReaders)}`,
      );

      expect(compiled).toContain(
        `[?rel-condition-relpage :block/uid "${RELATION_PAGE_UID}"]`,
      );
      expect(keysRead).toEqual([":sourceUid", ":destinationUid", ":hasSchema"]);
      if (schemaConstrained)
        expect(schemaConstants).toEqual([`"${reldata.hasSchema}"`]);
      else expect(schemaConstants).toEqual([]);
      if (destinationConstrained)
        expect(targetConstants).toContain(`"${reldata.destinationUid}"`);

      expect(
        tentativeReaders,
        "expected a clause that reads the tentative prop so pending instances are excluded",
      ).not.toEqual([]);
      expect(query).toContain(`:${TENTATIVE_PROP_KEY}`);
    },
  );
});
