const leafClauses = (clauses: DatalogClause[]): DatalogClause[] =>
  clauses.flatMap((c) => {
    switch (c.type) {
      case "not-join-clause":
      case "or-join-clause":
      case "not-clause":
      case "or-clause":
      case "and-clause":
        return leafClauses(c.clauses);
      default:
        return [c];
    }
  });

const compile = (clauses: DatalogClause[]): string[] =>
  clauses.map((c) => compileDatalog(c, 0));

const clausesReadingTentative = (clauses: DatalogClause[]): string[] =>
  compile(leafClauses(clauses)).filter((c) =>
    c.includes(`:${TENTATIVE_PROP_KEY}`),
