const reldataKeysRead = (clauses: DatalogClause[]): string[] =>
  leafClauses(clauses).flatMap((c) =>
    c.type === "fn-expr" &&
    c.fn === "get" &&
    c.arguments[0]?.type === "variable" &&
    c.arguments[0].value.endsWith("reldata") &&
    c.arguments[1]?.type === "constant"
      ? [c.arguments[1].value]
      : [],
  );

