  }),
  localRelation({
    id: "local-supports-b",
    label: "supports",
    ...CLAIM_SUPPORTS_CLAIM,
  }),
  LOCAL_INFORMS,
];

const ONE_SCHEMA_TWO_PATTERNS: DiscourseRelation[] = [
  localRelation({
    id: "local-supports-a",
    label: "Supports",
