const buildSource = (direction: Direction, spaceUri: string) => {
  const schemaRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "schema");
  const noteRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "note");

  const nodeSchemas: CrossAppNodeSchema[] = [
    {
      ...base,
      localId: "remote-claim-type",
      rid: schemaRid("remote-claim-type"),
      label: "Claim",
    },
    {
      ...base,
      localId: "remote-evidence-type",
      rid: schemaRid("remote-evidence-type"),
      label: "Evidence",
    },
  ];

  const relationType = (
    localId: string,
    label: string,
    complement: string,
  ): CrossAppRelationTypeSchema => ({
    ...base,
    localId,
    rid: schemaRid(localId),
    label,
    complement,
  });

  const triple = ({
    localId,
    label,
    complement,
    relationTypeId,
    sourceType,
    destinationType,
  }: {
    localId: string;
    label: string;
    complement: string;
    relationTypeId: string;
    sourceType: string;
    destinationType: string;
  }): CrossAppRelationTripleSchema =>
    direction === "OR"
      ? {
          ...base,
          localId,
          rid: schemaRid(localId),
          relation: relationTypeId,
          sourceType,
          destinationType,
        }
      : {
          ...base,
          localId,
          rid: schemaRid(localId),
          label,
          complement,
          sourceType,
          destinationType,
        };

  const relation = ({
    localId,
    relationType,
    source,
    destination,
  }: Pick<
    CrossAppRelation,
    "localId" | "relationType" | "source" | "destination"
  >): CrossAppRelation => ({
    ...base,
    localId,
    rid: spaceUriAndLocalIdToRid(spaceUri, localId, "relation"),
    relationType,
    source,
    destination,
  });

  const ambiguous = {
    relType: relationType("remote-supports-type", "Supports", "Supported By"),
    triple: triple({
      localId: "remote-supports-triple",
      label: "Supports",
      complement: "Supported By",
      relationTypeId: "remote-supports-type",
      sourceType: "remote-claim-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-supports",
      relationType: "remote-supports-triple",
      source: "remote-claim-a",
      destination: "remote-claim-b",
    }),
  };
  const independent = {
    relType: relationType("remote-informs-type", "Informs", "Informed By"),
    triple: triple({
      localId: "remote-informs-triple",
      label: "Informs",
      complement: "Informed By",
      relationTypeId: "remote-informs-type",
      sourceType: "remote-evidence-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-informs",
      relationType: "remote-informs-triple",
      source: "remote-evidence-a",
      destination: "remote-claim-a",
    }),
  };

  const importedPages: Record<string, string> = {
    [noteRid("remote-claim-a")]: "page-claim-a",
    [noteRid("remote-claim-b")]: "page-claim-b",
    [noteRid("remote-evidence-a")]: "page-evidence-a",
  };

  const discovery = (
    parts: (typeof ambiguous)[],
  ): Discovery & { order: string } => ({
    order: parts
      .map((p) => (p === ambiguous ? "ambiguous" : "independent"))
      .join(" -> "),
    nodeSchemas,
    relTypeSchemas: direction === "OR" ? parts.map((p) => p.relType) : [],
    relTripleSchemas: parts.map((p) => p.triple),
    relations: parts.map((p) => p.relation),
  });

  return {
    importedPages,
    byOrder: (order: Order) =>
      discovery(
        order === "ambiguous first"
          ? [ambiguous, independent]
          : [independent, ambiguous],
      ),
    independentOnly: () => discovery([independent]),
  };
};

const runImport = async ({
  label,
  localRelations,
  discovery,
  importedPages,
}: {
  label: string;
  localRelations: DiscourseRelation[];
  discovery: Discovery & { order: string };
