// REL-11 repro: pending (tentative) imported relations in query builder results.
// Drives the real writer (createReifiedRelation) and the real stored-relation
// translator (registerDiscourseDatalogTranslators -> conditionToDatalog ->
// getDatalogQuery). No Datalog engine runs, so the generated clause set stands
// in for the query results.
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { DatalogClause } from "roamjs-components/types";

const fixtures = vi.hoisted(() => {
  (globalThis as { window?: unknown }).window = {
    roamAlphaAPI: { util: { generateUID: () => "hoisted-uid" } },
  };
  const RELATION_PAGE_UID = "relations-page-uid";
  const SUPPORTS_SCHEMA_UID = "supports-schema-uid";
  const EVIDENCE_UID = "evidence-page-uid";
  const CLAIM_UID = "claim-page-uid";
  const node = (text: string, type: string, format: string) => ({
    text,
    type,
    format,
    shortcut: text[0],
    tag: "",
    specification: [],
    backedBy: "user" as const,
    canvasSettings: {},
  });
  return {
    RELATION_PAGE_UID,
    SUPPORTS_SCHEMA_UID,
    EVIDENCE_UID,
    CLAIM_UID,
    nodes: [
      node("Evidence", "_EVD-node", "[[EVD]] - {content}"),
      node("Claim", "_CLM-node", "[[CLM]] - {content}"),
    ],
    // An accepted (non-provisional) relation type: it is in the grammar that
    // getDiscourseRelations returns, with stored relations turned on.
    relations: [
      {
        id: SUPPORTS_SCHEMA_UID,
        label: "Supports",
        complement: "Supported By",
        source: "_EVD-node",
        destination: "_CLM-node",
        triples: [
          ["Page", "is a", "source"],
          ["Block", "references", "Page"],
          ["Block", "is in page", "ParentPage"],
          ["ParentPage", "is a", "destination"],
        ] as const,
      },
    ],
  };
});

vi.mock("roamjs-components/util/env", () => ({ getNodeEnv: () => "test" }));
vi.mock("roamjs-components/queries/getPageUidByPageTitle", () => ({
  default: () => fixtures.RELATION_PAGE_UID,
}));
vi.mock("roamjs-components/writes/createBlock", () => ({
  default: vi.fn(() => Promise.resolve("")),
}));
vi.mock("~/utils/internalError", () => ({ default: vi.fn() }));
vi.mock("~/utils/predefinedSelections", () => ({ default: [] }));
vi.mock("~/utils/storedRelations", () => ({
  getStoredRelationsEnabled: () => true,
}));
// Same constants as deriveDiscourseNodeAttribute.ts:9-10; the real module
// pulls in the discourse-context stack, which this repro does not need.
vi.mock("~/utils/deriveDiscourseNodeAttribute", () => ({
  ANY_RELATION_NAME: "Has Any Relation To",
  ANY_RELATION_REGEX: /Has Any Relation To/i,
}));
