import createBlock from "roamjs-components/writes/createBlock";
import compileDatalog from "~/utils/compileDatalog";
import conditionToDatalog from "~/utils/conditionToDatalog";
import {
  DISCOURSE_GRAPH_PROP_NAME,
  TENTATIVE_PROP_KEY,
  createReifiedRelation,
} from "~/utils/createReifiedBlock";
import { getDatalogQuery } from "~/utils/fireQuery";
import registerDiscourseDatalogTranslators from "~/utils/registerDiscourseDatalogTranslators";
import type { QBClause } from "~/utils/types";

const { RELATION_PAGE_UID, SUPPORTS_SCHEMA_UID, EVIDENCE_UID, CLAIM_UID } =
  fixtures;

let uidCounter = 0;

beforeEach(() => {
  vi.mocked(createBlock).mockClear();
  uidCounter = 0;
  (globalThis as { window: unknown }).window = {
    roamAlphaAPI: {
      util: { generateUID: () => `generated-uid-${++uidCounter}` },
      pull: (_pattern: string, [attr, value]: [string, string]) =>
        attr === ":block/uid" && [EVIDENCE_UID, CLAIM_UID].includes(value)
          ? { ":db/id": 1 }
          : null,
      data: { async: { q: vi.fn(() => Promise.resolve([])) } },
    },
  };
});

// Same call importSharedRelations.ts:228-233 makes for every imported relation
// instance with no local twin.
const writePendingImportedInstance = async () => {
  const instanceUid = await createReifiedRelation({
    sourceUid: EVIDENCE_UID,
    destinationUid: CLAIM_UID,
    relationBlockUid: SUPPORTS_SCHEMA_UID,
    tentative: true,
  });
  const [args] = vi.mocked(createBlock).mock.calls[0];
  const { props } = args.node;
  if (props === undefined) throw new Error("writer wrote no block props");
  return { instanceUid, parentUid: args.parentUid, props };
};

const leafClauses = (clauses: DatalogClause[]): DatalogClause[] =>
  clauses.flatMap((c) => {
    switch (c.type) {
      case "not-join-clause":
      case "or-join-clause":
      case "not-clause":
      case "or-clause":
      case "and-clause":
        return leafClauses(c.clauses);
      default:
        return [c];
    }
  });

const compile = (clauses: DatalogClause[]): string[] =>
  clauses.map((c) => compileDatalog(c, 0));

const clausesReadingTentative = (clauses: DatalogClause[]): string[] =>
  compile(leafClauses(clauses)).filter((c) =>
    c.includes(`:${TENTATIVE_PROP_KEY}`),
  );

const reldataKeysRead = (clauses: DatalogClause[]): string[] =>
  leafClauses(clauses).flatMap((c) =>
    c.type === "fn-expr" &&
    c.fn === "get" &&
    c.arguments[0]?.type === "variable" &&
    c.arguments[0].value.endsWith("reldata") &&
    c.arguments[1]?.type === "constant"
      ? [c.arguments[1].value]
      : [],
  );

const equalityConstantsFor = (
  clauses: DatalogClause[],
  variableSuffix: string,
): string[] =>
  leafClauses(clauses).flatMap((c) =>
    c.type === "pred-expr" &&
    c.pred === "=" &&
    c.arguments[0]?.type === "variable" &&
    c.arguments[0].value.endsWith(variableSuffix) &&
    c.arguments[1]?.type === "constant"
      ? [c.arguments[1].value]
      : [],
  );

const relationCondition = (target: string, relation: string): QBClause => ({
  type: "clause",
  uid: "rel-condition",
  source: "node",
  relation,
  target,
  not: false,
});

const cases = [
  {
    name: "node Supports Claim (node-type target)",
    condition: relationCondition("Claim", "Supports"),
    schemaConstrained: true,
    destinationConstrained: false,
  },
  {
    name: "node Supports <claim page uid> (specific-node target)",
    condition: relationCondition(CLAIM_UID, "Supports"),
    schemaConstrained: true,
    destinationConstrained: true,
  },
  {
    name: "node Has Any Relation To <claim page uid>",
    condition: relationCondition(CLAIM_UID, "Has Any Relation To"),
    schemaConstrained: false,
    destinationConstrained: true,
  },
];

describe("REL-11 pending relations in query results (Roam, stored relations on)", () => {
  it.each(cases)(
    "the generated query excludes pending instances: $name",
    async ({ name, condition, schemaConstrained, destinationConstrained }) => {
      const pending = await writePendingImportedInstance();
      const reldata = pending.props[DISCOURSE_GRAPH_PROP_NAME] as Record<
        string,
        string
      >;
      console.log(
        `ACTUAL [${name}] tentative prop key: "${TENTATIVE_PROP_KEY}"`,
      );
      console.log(
        `ACTUAL [${name}] pending block written under parent ${pending.parentUid} with props: ${JSON.stringify(pending.props)}`,
      );
      expect(TENTATIVE_PROP_KEY).toBe("tentative");
      expect(pending.parentUid).toBe(RELATION_PAGE_UID);
      expect(pending.props).toEqual({
        [DISCOURSE_GRAPH_PROP_NAME]: {
          sourceUid: EVIDENCE_UID,
          destinationUid: CLAIM_UID,
          [TENTATIVE_PROP_KEY]: "true",
          hasSchema: SUPPORTS_SCHEMA_UID,
        },
      });

      registerDiscourseDatalogTranslators();
      const clauses = conditionToDatalog(condition);
      const compiled = compile(clauses);
      const { query } = getDatalogQuery({
        returnNode: "node",
        conditions: [
          {
            type: "clause",
            uid: "isa-condition",
            source: "node",
            relation: "is a",
            target: "Evidence",
            not: false,
          },
          condition,
        ],
        selections: [],
      });
      const keysRead = reldataKeysRead(clauses);
      const tentativeReaders = clausesReadingTentative(clauses);
      const schemaConstants = equalityConstantsFor(clauses, "-relSchema");
      const targetConstants = equalityConstantsFor(clauses, "-relTarget");

      console.log(
        `ACTUAL [${name}] stored-relation translator clauses:\n${compiled.join("\n")}`,
      );
      console.log(`ACTUAL [${name}] full query builder query:\n${query}`);
      console.log(
        `ACTUAL [${name}] keys read from the stored relation's discourse-graph prop: ${JSON.stringify(keysRead)}`,
      );
      console.log(
        `ACTUAL [${name}] relSchema constraints: ${JSON.stringify(schemaConstants)}; relTarget constraints: ${JSON.stringify(targetConstants)}; pending block values: hasSchema="${reldata.hasSchema}", destinationUid="${reldata.destinationUid}"`,
      );
      console.log(
        `ACTUAL [${name}] clauses that read :${TENTATIVE_PROP_KEY}: ${JSON.stringify(tentativeReaders)}`,
      );

      expect(compiled).toContain(
        `[?rel-condition-relpage :block/uid "${RELATION_PAGE_UID}"]`,
      );
      expect(keysRead).toEqual([":sourceUid", ":destinationUid", ":hasSchema"]);
      if (schemaConstrained)
        expect(schemaConstants).toEqual([`"${reldata.hasSchema}"`]);
      else expect(schemaConstants).toEqual([]);
      if (destinationConstrained)
        expect(targetConstants).toContain(`"${reldata.destinationUid}"`);

      expect(
        tentativeReaders,
        "expected a clause that reads the tentative prop so pending instances are excluded",
      ).not.toEqual([]);
      expect(query).toContain(`:${TENTATIVE_PROP_KEY}`);
    },
  );
});
/**
 * REL-10 repro: one bad relation stops all relations (Roam destination, RR and OR).
 * Two local relation schemas with distinct ids share a label and endpoint types, so
 * one incoming triple schema matches both. The case row expects every other relation
 * to still import. Only discovery, settings reads, Roam lookups and block writes are
 * mocked; schema matching and the instance loop are the real importSharedRelations.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import type {
  CrossAppNodeSchema,
  CrossAppRelation,
  CrossAppRelationTripleSchema,
  CrossAppRelationTypeSchema,
} from "@repo/database/crossAppContracts";
import type { DGSupabaseClient } from "@repo/database/lib/client";
import { spaceUriAndLocalIdToRid } from "@repo/database/lib/rid";
import { createReifiedRelation } from "~/utils/createReifiedBlock";
import { createRelationSchema } from "~/utils/createRelationSchema";
import { discoverSharedRelations } from "~/utils/discoverSharedRelations";
import getDiscourseRelations, {
  type DiscourseRelation,
} from "~/utils/getDiscourseRelations";
import { getErrorMessage } from "~/utils/getErrorMessage";
import { findImportedNodeUidBySourceRid } from "~/utils/importedSourceIdentity";
import { importSharedRelations } from "~/utils/importSharedRelations";
import refreshConfigTree from "~/utils/refreshConfigTree";

vi.hoisted(() => {
  vi.stubGlobal("window", {
    roamAlphaAPI: {
      graph: { name: "local" },
      data: { async: { fast: { q: () => Promise.resolve([]) } } },
    },
  });
});
vi.mock("~/utils/refreshConfigTree", () => ({ default: vi.fn() }));
vi.mock("~/utils/getDiscourseRelations", () => ({ default: vi.fn() }));
vi.mock("~/utils/getDiscourseNodes", () => ({
  default: () => [
    { type: "local-claim", text: "Claim" },
    { type: "local-evidence", text: "Evidence" },
  ],
}));
vi.mock("~/utils/importedSourceIdentity", () => ({
  getImportedSourceRids: () => Promise.resolve(new Set<string>()),
  findImportedNodeUidBySourceRid: vi.fn(),
  writeImportedSourceIdentity: vi.fn(),
}));
vi.mock("~/components/settings/utils/accessors", () => ({
  createDiscourseNodeType: vi.fn(),
}));
vi.mock("~/utils/createRelationSchema", () => ({
  createRelationSchema: vi.fn(),
}));
vi.mock("~/utils/createReifiedBlock", () => ({
  getReifiedRelations: () => Promise.resolve([]),
  createReifiedRelation: vi.fn(),
}));
vi.mock("roamjs-components/writes", () => ({ deleteBlock: vi.fn() }));
vi.mock("~/utils/discoverSharedRelations", () => ({
  discoverSharedRelations: vi.fn(),
}));

type Direction = "OR" | "RR";
type Order = "ambiguous first" | "independent first";
type Discovery = Awaited<ReturnType<typeof discoverSharedRelations>>;

const client = {} as DGSupabaseClient;
const base = {
  authorId: "remote-author",
  createdAt: new Date("2026-09-01T00:00:00Z"),
};

const localRelation = ({
  id,
  label,
  source,
  destination,
  triples = [],
}: Omit<DiscourseRelation, "complement" | "triples"> &
  Partial<Pick<DiscourseRelation, "triples">>): DiscourseRelation => ({
  id,
  label,
  complement: `${label} (complement)`,
  source,
  destination,
  triples,
});

const CLAIM_SUPPORTS_CLAIM = {
  source: "local-claim",
  destination: "local-claim",
};
const LOCAL_INFORMS = localRelation({
  id: "local-informs",
  label: "Informs",
  source: "local-evidence",
  destination: "local-claim",
});

const TWO_SCHEMAS_SAME_LABEL: DiscourseRelation[] = [
  localRelation({
    id: "local-supports-a",
    label: "Supports",
    ...CLAIM_SUPPORTS_CLAIM,
  }),
  localRelation({
    id: "local-supports-b",
    label: "supports",
    ...CLAIM_SUPPORTS_CLAIM,
  }),
  LOCAL_INFORMS,
];

const ONE_SCHEMA_TWO_PATTERNS: DiscourseRelation[] = [
  localRelation({
    id: "local-supports-a",
    label: "Supports",
    ...CLAIM_SUPPORTS_CLAIM,
    triples: [["source", "references", "destination"]],
  }),
  localRelation({
    id: "local-supports-a",
    label: "Supports",
    ...CLAIM_SUPPORTS_CLAIM,
    triples: [["source", "is in page", "destination"]],
  }),
  LOCAL_INFORMS,
];

const INDEPENDENT_CREATED = {
  sourceUid: "page-evidence-a",
  destinationUid: "page-claim-a",
  relationBlockUid: "local-informs",
  tentative: true,
};
const AMBIGUOUS_CREATED_ON_SCHEMA_A = {
  sourceUid: "page-claim-a",
  destinationUid: "page-claim-b",
  relationBlockUid: "local-supports-a",
  tentative: true,
};

const buildSource = (direction: Direction, spaceUri: string) => {
  const schemaRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "schema");
  const noteRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "note");

  const nodeSchemas: CrossAppNodeSchema[] = [
    {
      ...base,
      localId: "remote-claim-type",
      rid: schemaRid("remote-claim-type"),
      label: "Claim",
    },
    {
      ...base,
      localId: "remote-evidence-type",
      rid: schemaRid("remote-evidence-type"),
      label: "Evidence",
    },
  ];

  const relationType = (
    localId: string,
    label: string,
    complement: string,
  ): CrossAppRelationTypeSchema => ({
    ...base,
    localId,
    rid: schemaRid(localId),
    label,
    complement,
  });

  const triple = ({
    localId,
    label,
    complement,
    relationTypeId,
    sourceType,
    destinationType,
  }: {
    localId: string;
    label: string;
    complement: string;
    relationTypeId: string;
    sourceType: string;
    destinationType: string;
  }): CrossAppRelationTripleSchema =>
    direction === "OR"
      ? {
          ...base,
          localId,
          rid: schemaRid(localId),
          relation: relationTypeId,
          sourceType,
          destinationType,
        }
      : {
          ...base,
          localId,
          rid: schemaRid(localId),
          label,
          complement,
          sourceType,
          destinationType,
        };

  const relation = ({
    localId,
    relationType,
    source,
    destination,
  }: Pick<
    CrossAppRelation,
    "localId" | "relationType" | "source" | "destination"
  >): CrossAppRelation => ({
    ...base,
    localId,
    rid: spaceUriAndLocalIdToRid(spaceUri, localId, "relation"),
    relationType,
    source,
    destination,
  });

  const ambiguous = {
    relType: relationType("remote-supports-type", "Supports", "Supported By"),
    triple: triple({
      localId: "remote-supports-triple",
      label: "Supports",
      complement: "Supported By",
      relationTypeId: "remote-supports-type",
      sourceType: "remote-claim-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-supports",
      relationType: "remote-supports-triple",
      source: "remote-claim-a",
      destination: "remote-claim-b",
    }),
  };
  const independent = {
    relType: relationType("remote-informs-type", "Informs", "Informed By"),
    triple: triple({
      localId: "remote-informs-triple",
      label: "Informs",
      complement: "Informed By",
      relationTypeId: "remote-informs-type",
      sourceType: "remote-evidence-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-informs",
      relationType: "remote-informs-triple",
      source: "remote-evidence-a",
      destination: "remote-claim-a",
    }),
  };

  const importedPages: Record<string, string> = {
    [noteRid("remote-claim-a")]: "page-claim-a",
    [noteRid("remote-claim-b")]: "page-claim-b",
    [noteRid("remote-evidence-a")]: "page-evidence-a",
  };

  const discovery = (
    parts: (typeof ambiguous)[],
  ): Discovery & { order: string } => ({
    order: parts
      .map((p) => (p === ambiguous ? "ambiguous" : "independent"))
      .join(" -> "),
    nodeSchemas,
    relTypeSchemas: direction === "OR" ? parts.map((p) => p.relType) : [],
    relTripleSchemas: parts.map((p) => p.triple),
    relations: parts.map((p) => p.relation),
  });

  return {
    importedPages,
    byOrder: (order: Order) =>
      discovery(
        order === "ambiguous first"
          ? [ambiguous, independent]
          : [independent, ambiguous],
      ),
    independentOnly: () => discovery([independent]),
  };
};

const runImport = async ({
  label,
  localRelations,
  discovery,
  importedPages,
}: {
  label: string;
  localRelations: DiscourseRelation[];
  discovery: Discovery & { order: string };
  importedPages: Record<string, string>;
}) => {
  vi.mocked(getDiscourseRelations).mockReturnValue(localRelations);
  vi.mocked(discoverSharedRelations).mockResolvedValue(discovery);
  vi.mocked(findImportedNodeUidBySourceRid).mockImplementation((rid) =>
    Promise.resolve(importedPages[rid] ?? null),
  );
  vi.mocked(createReifiedRelation).mockImplementation(
    ({ relationBlockUid, sourceUid }) =>
      Promise.resolve(`reified-${relationBlockUid}-${sourceUid}`),
  );

  let thrown: unknown;
  try {
    await importSharedRelations(client, 7);
  } catch (error) {
    thrown = error;
  }
  const created = vi
    .mocked(createReifiedRelation)
    .mock.calls.map(([args]) => args);
  const outcome =
    thrown === undefined
      ? "resolved"
      : `rejected with "${getErrorMessage(thrown)}"`;
  console.log(
    `ACTUAL [${label}] processing order ${discovery.order}: importSharedRelations ${outcome}; ` +
      `reified relations created: ${JSON.stringify(created)}; ` +
      `endpoint lookups (instance loop reached): ${vi.mocked(findImportedNodeUidBySourceRid).mock.calls.length}; ` +
      `createRelationSchema calls: ${vi.mocked(createRelationSchema).mock.calls.length}; ` +
      `refreshConfigTree calls: ${vi.mocked(refreshConfigTree).mock.calls.length}`,
  );
  if (thrown !== undefined) {
    console.log(
      `ACTUAL [${label}] dialog text from the DiscoverSharedNodesDialog.tsx:346 template: ` +
        `"The nodes were imported, but their relations were not: ${getErrorMessage(thrown)}"`,
    );
  }
  return { thrown, created };
};

beforeEach(() => vi.clearAllMocks());

describe.each([
  { direction: "OR" as const, spaceUri: "obsidian:remote-vault" },
  {
    direction: "RR" as const,
    spaceUri: "https://roamresearch.com/#/app/remote-graph",
  },
])("REL-10 ($direction)", ({ direction, spaceUri }) => {
