  tentative: true,
};

const buildSource = (direction: Direction, spaceUri: string) => {
  const schemaRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "schema");
  const noteRid = (localId: string) =>
    spaceUriAndLocalIdToRid(spaceUri, localId, "note");

  const nodeSchemas: CrossAppNodeSchema[] = [
    {
      ...base,
      localId: "remote-claim-type",
      rid: schemaRid("remote-claim-type"),
      label: "Claim",
    },
    {
      ...base,
      localId: "remote-evidence-type",
      rid: schemaRid("remote-evidence-type"),
      label: "Evidence",
    },
  ];

  const relationType = (
    localId: string,
    label: string,
    complement: string,
  ): CrossAppRelationTypeSchema => ({
    ...base,
    localId,
    rid: schemaRid(localId),
    label,
    complement,
  });

  const triple = ({
    localId,
    label,
    complement,
    relationTypeId,
    sourceType,
    destinationType,
  }: {
    localId: string;
    label: string;
    complement: string;
    relationTypeId: string;
    sourceType: string;
    destinationType: string;
  }): CrossAppRelationTripleSchema =>
    direction === "OR"
      ? {
          ...base,
          localId,
          rid: schemaRid(localId),
          relation: relationTypeId,
          sourceType,
          destinationType,
        }
      : {
          ...base,
          localId,
          rid: schemaRid(localId),
          label,
          complement,
          sourceType,
          destinationType,
        };

  const relation = ({
    localId,
    relationType,
    source,
    destination,
  }: Pick<
    CrossAppRelation,
    "localId" | "relationType" | "source" | "destination"
  >): CrossAppRelation => ({
    ...base,
    localId,
    rid: spaceUriAndLocalIdToRid(spaceUri, localId, "relation"),
    relationType,
    source,
    destination,
  });

  const ambiguous = {
    relType: relationType("remote-supports-type", "Supports", "Supported By"),
    triple: triple({
      localId: "remote-supports-triple",
      label: "Supports",
      complement: "Supported By",
      relationTypeId: "remote-supports-type",
      sourceType: "remote-claim-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-supports",
      relationType: "remote-supports-triple",
      source: "remote-claim-a",
      destination: "remote-claim-b",
    }),
  };
  const independent = {
    relType: relationType("remote-informs-type", "Informs", "Informed By"),
    triple: triple({
      localId: "remote-informs-triple",
      label: "Informs",
      complement: "Informed By",
      relationTypeId: "remote-informs-type",
      sourceType: "remote-evidence-type",
      destinationType: "remote-claim-type",
    }),
    relation: relation({
      localId: "remote-rel-informs",
      relationType: "remote-informs-triple",
      source: "remote-evidence-a",
      destination: "remote-claim-a",
    }),
  };

  const importedPages: Record<string, string> = {
    [noteRid("remote-claim-a")]: "page-claim-a",
    [noteRid("remote-claim-b")]: "page-claim-b",
    [noteRid("remote-evidence-a")]: "page-evidence-a",
  };

  const discovery = (
    parts: (typeof ambiguous)[],
  ): Discovery & { order: string } => ({
    order: parts
      .map((p) => (p === ambiguous ? "ambiguous" : "independent"))
      .join(" -> "),
    nodeSchemas,
    relTypeSchemas: direction === "OR" ? parts.map((p) => p.relType) : [],
    relTripleSchemas: parts.map((p) => p.triple),
    relations: parts.map((p) => p.relation),
  });

  return {
    importedPages,
    byOrder: (order: Order) =>
      discovery(
        order === "ambiguous first"
          ? [ambiguous, independent]
          : [independent, ambiguous],
      ),
    independentOnly: () => discovery([independent]),
  };
};

const runImport = async ({
  label,
  localRelations,
  discovery,
  importedPages,
}: {
  label: string;
  localRelations: DiscourseRelation[];
  discovery: Discovery & { order: string };
  importedPages: Record<string, string>;
}) => {
  vi.mocked(getDiscourseRelations).mockReturnValue(localRelations);
  vi.mocked(discoverSharedRelations).mockResolvedValue(discovery);
  vi.mocked(findImportedNodeUidBySourceRid).mockImplementation((rid) =>
    Promise.resolve(importedPages[rid] ?? null),
  );
  vi.mocked(createReifiedRelation).mockImplementation(
    ({ relationBlockUid, sourceUid }) =>
      Promise.resolve(`reified-${relationBlockUid}-${sourceUid}`),
  );

  let thrown: unknown;
  try {
    await importSharedRelations(client, 7);
  } catch (error) {
    thrown = error;
  }
  const created = vi
    .mocked(createReifiedRelation)
    .mock.calls.map(([args]) => args);
  const outcome =
    thrown === undefined
      ? "resolved"
      : `rejected with "${getErrorMessage(thrown)}"`;
  console.log(
    `ACTUAL [${label}] processing order ${discovery.order}: importSharedRelations ${outcome}; ` +
      `reified relations created: ${JSON.stringify(created)}; ` +
      `endpoint lookups (instance loop reached): ${vi.mocked(findImportedNodeUidBySourceRid).mock.calls.length}; ` +
      `createRelationSchema calls: ${vi.mocked(createRelationSchema).mock.calls.length}; ` +
      `refreshConfigTree calls: ${vi.mocked(refreshConfigTree).mock.calls.length}`,
  );
  if (thrown !== undefined) {
    console.log(
      `ACTUAL [${label}] dialog text from the DiscoverSharedNodesDialog.tsx:346 template: ` +
        `"The nodes were imported, but their relations were not: ${getErrorMessage(thrown)}"`,
    );
  }
  return { thrown, created };
};

beforeEach(() => vi.clearAllMocks());

describe.each([
  { direction: "OR" as const, spaceUri: "obsidian:remote-vault" },
  {
    direction: "RR" as const,
    spaceUri: "https://roamresearch.com/#/app/remote-graph",
  },
])("REL-10 ($direction)", ({ direction, spaceUri }) => {
  const source = buildSource(direction, spaceUri);

  it.each(["ambiguous first", "independent first"] as const)(
    "creates the independent relation when another relation matches two local schemas (%s)",
    async (order) => {
      const { created } = await runImport({
        label: `${direction}, two schemas same label`,
        localRelations: TWO_SCHEMAS_SAME_LABEL,
        discovery: source.byOrder(order),
        importedPages: source.importedPages,
      });
      expect(created).toContainEqual(INDEPENDENT_CREATED);
    },
  );

  it("control: creates both relations when one local schema has two query patterns under the same id", async () => {
    const { thrown, created } = await runImport({
      label: `${direction}, one schema two patterns`,
      localRelations: ONE_SCHEMA_TWO_PATTERNS,
      discovery: source.byOrder("ambiguous first"),
      importedPages: source.importedPages,
    });
    expect(thrown).toBeUndefined();
    expect(createRelationSchema).not.toHaveBeenCalled();
    expect(created).toContainEqual(AMBIGUOUS_CREATED_ON_SCHEMA_A);
    expect(created).toContainEqual(INDEPENDENT_CREATED);
  });

  it("control: creates the independent relation when it is the only one discovered", async () => {
    const { thrown, created } = await runImport({
      label: `${direction}, independent only`,
      localRelations: TWO_SCHEMAS_SAME_LABEL,
      discovery: source.independentOnly(),
      importedPages: source.importedPages,
    });
    expect(thrown).toBeUndefined();
    expect(created).toEqual([INDEPENDENT_CREATED]);
  });
});


