  },
])("REL-10 ($direction)", ({ direction, spaceUri }) => {
  const source = buildSource(direction, spaceUri);

  it.each(["ambiguous first", "independent first"] as const)(
    "creates the independent relation when another relation matches two local schemas (%s)",
    async (order) => {
      const { created } = await runImport({
        label: `${direction}, two schemas same label`,
        localRelations: TWO_SCHEMAS_SAME_LABEL,
