    },
  );

  it("control: creates both relations when one local schema has two query patterns under the same id", async () => {
    const { thrown, created } = await runImport({
      label: `${direction}, one schema two patterns`,
      localRelations: ONE_SCHEMA_TWO_PATTERNS,
      discovery: source.byOrder("ambiguous first"),
