export const createRelationSchema = async ({
  label,
  complement,
  source,
  destination,
}: {
  label: string;
  complement: string;
  source: string;
  destination: string;
}) => {
  const grammarNode = discourseConfigRef.tree.find(
    (node) => node.text === "grammar",
