import { RoamBasicNode } from "roamjs-components/types/native";
import getSettingValueFromTree from "roamjs-components/util/getSettingValueFromTree";
import getSubTree from "roamjs-components/util/getSubTree";
import createBlock from "roamjs-components/writes/createBlock";
import { Column, Condition, Selection } from "./types";

export const roamNodeToCondition = ({
  uid,
  children,
  text,
}: RoamBasicNode): Condition => {
  const type = (
    isNaN(Number(text))
      ? text
      : !!getSubTree({ tree: children, key: "not" }).uid
        ? "not"
        : "clause"
  ) as Condition["type"];
  return type === "clause" || type === "not"
    ? {
        uid,
        source: getSettingValueFromTree({ tree: children, key: "source" }),
        target: getSettingValueFromTree({ tree: children, key: "target" }),
        relation: getSettingValueFromTree({
          tree: children,
          key: "relation",
        }),
        type,

        // @deprecated
        not: type === "not" || !!getSubTree({ tree: children, key: "not" }).uid,
      }
    : {
        uid,
        type,
        conditions: children.map((node) =>
          node.children.map(roamNodeToCondition),
        ),
      };
};

type ParseQuery = (q: RoamBasicNode | string) => {
  returnNode: string;
  conditions: Condition[];
  selections: Selection[];
  customNode: string;
  returnNodeUid: string;
  conditionsNodesUid: string;
  selectionsNodesUid: string;
  customNodeUid: string;
  isCustomEnabled: boolean;
  columns: Column[];
};

export const DEFAULT_RETURN_NODE = "node";

export const parseQuery: ParseQuery = (parentUidOrNode) => {
  const queryNode =
    typeof parentUidOrNode === "string"
      ? getSubTree({ key: "scratch", parentUid: parentUidOrNode })
      : parentUidOrNode;
  const { uid, children } = queryNode;
  const getOrCreateUid = (sub: RoamBasicNode, text: string) => {
    if (sub.uid) return sub.uid;
    const newUid = window.roamAlphaAPI.util.generateUID();
    createBlock({
      node: { text, uid: newUid },
      parentUid: uid,
    });
    return newUid;
  };
  const conditionsNode = getSubTree({
    tree: children,
    key: "conditions",
  });
  const conditionsNodesUid = getOrCreateUid(conditionsNode, "conditions");
  const conditions = conditionsNode.children.map(roamNodeToCondition);

  const selectionsNode = getSubTree({ tree: children, key: "selections" });
  const selectionsNodesUid = getOrCreateUid(selectionsNode, "selections");

  const selections = selectionsNode.children.map(({ uid, text, children }) => ({
    uid,
    text,
    label: children?.[0]?.text || "",
  }));

  const customBlock = getSubTree({ tree: children, key: "custom" });
  const customNodeUid = getOrCreateUid(customBlock, "custom");
  const returnNodeUid = `returnuid`;
  return {
    returnNode: DEFAULT_RETURN_NODE,
    conditions,
    selections,
    customNode: customBlock.children[0]?.text || "",
    returnNodeUid,
    conditionsNodesUid,
    selectionsNodesUid,
    customNodeUid,
    isCustomEnabled: customBlock.children[1]?.text === "enabled",
    columns: [
      {
        key:
          selections.find((s) => s.text === DEFAULT_RETURN_NODE)?.label ||
          "text",
        uid: returnNodeUid,
        selection: DEFAULT_RETURN_NODE,
      },
    ].concat(
      selections
        .filter((s) => s.text !== DEFAULT_RETURN_NODE)
        .map((s) => ({ uid: s.uid, key: s.label, selection: s.text })),
    ),
  };
};

export default parseQuery;
import type { OnloadArgs } from "roamjs-components/types/native";
import fireQuery, { QueryArgs } from "./fireQuery";
import parseQuery from "./parseQuery";
import parseResultSettings from "./parseResultSettings";
import postProcessResults from "./postProcessResults";
import { Column } from "./types";

const runQuery = ({
  parentUid,
  extensionAPI,
  inputs,
}: {
  parentUid: string;
  extensionAPI: OnloadArgs["extensionAPI"];
  inputs?: QueryArgs["inputs"];
}) => {
  const queryArgs = Object.assign(parseQuery(parentUid), { inputs });
  return fireQuery(queryArgs).then((results) => {
    const settings = parseResultSettings(
      parentUid,
      [
        {
          key: "text",
          uid: window.roamAlphaAPI.util.generateUID(),
          selection: "node",
        } as Column,
      ].concat(
        queryArgs.selections.map((s) => ({
          key: s.label,
          uid: s.uid,
          selection: s.text,
        })),
      ),
      extensionAPI,
    );
    return postProcessResults(results, settings);
  });
};

export default runQuery;
import createBlock from "roamjs-components/writes/createBlock";
import createPage from "roamjs-components/writes/createPage";
import getPageUidByPageTitle from "roamjs-components/queries/getPageUidByPageTitle";
import getBlockProps, { isJsonObject, type json } from "./getBlockProps";
import { setBlockPropsAsync } from "./setBlockProps";
import internalError from "./internalError";

export const DISCOURSE_GRAPH_PROP_NAME = "discourse-graph";
export const TENTATIVE_PROP_KEY = "tentative";
export const IMPORTED_FROM_PROP_KEY = "importedFrom";

// Annotations describe a relation's review/provenance state; they are not part
// of its identity, so lookups by role parameters must ignore them.
const RELATION_ANNOTATION_KEYS = new Set<string>([
  TENTATIVE_PROP_KEY,
  IMPORTED_FROM_PROP_KEY,
]);

const countRoleKeys = (params: Record<string, unknown>): number =>
  Object.keys(params).filter((k) => !RELATION_ANNOTATION_KEYS.has(k)).length;

const SANE_ROLE_NAME_RE = new RegExp(/^[\w-]*$/);

export const strictQueryForReifiedBlocks = async (
  parameterUids: Record<string, string>,
  { acceptedOnly = false }: { acceptedOnly?: boolean } = {},
): Promise<string | null> => {
  const paramsAsSeq = Object.entries(parameterUids);
  // validate parameter names
  if (
    Object.keys(parameterUids).filter((k) => !k.match(SANE_ROLE_NAME_RE)).length
  )
    throw new Error(
      `invalid parameter names in ${Object.keys(parameterUids).join(", ")}`,
    );
  const query = `[:find ?u ?d
  :in $ ${paramsAsSeq.map(([k]) => "?" + k).join(" ")}
  :where [?s :block/uid ?u] [?s :block/props ?p] [(get ?p :${DISCOURSE_GRAPH_PROP_NAME}) ?d]
  ${paramsAsSeq.map(([k]) => `[(get ?d :${k}) ?${k}]`).join(" ")} ]`;
  const result = (await window.roamAlphaAPI.data.async.q(
    query,
    ...paramsAsSeq.map(([, v]) => v),
  )) as [string, Record<string, string>][];
  // post-filtering because cannot filter by number of keys in datascript
  const numParams = countRoleKeys(parameterUids);
  const resultF = result
    .filter(
      ([, params]) =>
        countRoleKeys(params) === numParams &&
        (!acceptedOnly || params[TENTATIVE_PROP_KEY] !== "true"),
    )
    .map(([uid]) => uid);
  if (resultF.length > 1) {
    const paramsAsText = Object.entries(parameterUids)
      .map(([k, v]) => `${k}: '${v}'`)
      .join(", ");
    console.warn(
      `${resultF.length} results in strict query for {${paramsAsText}}`,
    );
  }
  return resultF.length > 0 ? resultF[0] : null;
};

export const acceptTentativeRelationInstance = async ({
  instanceUid,
}: {
  instanceUid: string;
}): Promise<void> => {
  const existing = getBlockProps(instanceUid)[DISCOURSE_GRAPH_PROP_NAME];
  if (!isJsonObject(existing) || typeof existing.sourceUid !== "string") {
    throw new Error(
      "The relation block could not be read. It may have been deleted; refresh and try again.",
    );
  }
  if (existing[TENTATIVE_PROP_KEY] === undefined) return;
  const accepted = { ...existing };
  delete accepted[TENTATIVE_PROP_KEY];
  await setBlockPropsAsync(instanceUid, {
    [DISCOURSE_GRAPH_PROP_NAME]: accepted,
  });
};

const createReifiedBlock = async ({
  destinationBlockUid,
  schemaUid,
  parameterUids,
}: {
  destinationBlockUid: string;
  schemaUid: string;
  parameterUids: Record<string, string>;
}): Promise<string> => {
  // TODO: Check that the parameterUids keys correspond to the schema
  const data = {
    ...parameterUids,
    hasSchema: schemaUid,
  };
  const existing = await strictQueryForReifiedBlocks(data);
  if (existing !== null) {
    // Deliberate local creation counts as user acceptance, so a dedupe hit on
    // a tentative imported block promotes it instead of returning a block the
    // UI hides as pending review. Best-effort: the relation exists either way.
    if (parameterUids[TENTATIVE_PROP_KEY] === undefined) {
      try {
        await acceptTentativeRelationInstance({ instanceUid: existing });
      } catch (error) {
        internalError({
          error,
          type: "Promote Tentative Relation On Create Failed",
          context: { instanceUid: existing },
          sendEmail: false,
        });
      }
    }
    return existing;
  }
  const newUid = window.roamAlphaAPI.util.generateUID();
  await createBlock({
    node: {
      text: newUid,
      uid: newUid,
      props: {
        [DISCOURSE_GRAPH_PROP_NAME]: data,
      },
    },
    parentUid: destinationBlockUid,
    order: "last",
  });
  return newUid;
};

const RELATION_PAGE_TITLE = "roam/js/discourse-graph/relations";
let relationPageUid: string | undefined = undefined;

const getOrCreateRelationPageUid = async (): Promise<string> => {
  if (relationPageUid === undefined) {
    relationPageUid = getPageUidByPageTitle(RELATION_PAGE_TITLE);
    if (relationPageUid === "") {
      relationPageUid = await createPage({ title: RELATION_PAGE_TITLE });
    }
  }
  return relationPageUid;
};

export const getExistingRelationPageUid = (): string | undefined => {
  if (relationPageUid === undefined) {
    const uid = getPageUidByPageTitle(RELATION_PAGE_TITLE);
    if (uid !== "") relationPageUid = uid;
  }
  return relationPageUid;
};

export const countReifiedRelations = async (): Promise<number> => {
  const pageUid = getExistingRelationPageUid();
  if (pageUid === undefined) return 0;
  const r = await window.roamAlphaAPI.data.async.q(
    `[:find (count ?c) :where [?p :block/children ?c] [?p :block/uid "${pageUid}"]]`,
  );
  return (r[0] || [0])[0] as number;
};

export type ReifiedRelationData = {
  sourceUid: string;
  destinationUid: string;
  hasSchema: string;
  tentative?: string;
  importedFrom?: json;
  importedFromRid?: string;
};

export type ReifiedRelationDataWithRelId = ReifiedRelationData & {
  relationId: string;
};

export const getReifiedRelations = async (): Promise<
  ReifiedRelationDataWithRelId[]
> => {
  const pageUid = getExistingRelationPageUid();
  if (pageUid === undefined) return [];
  const r = await window.roamAlphaAPI.data.async.q(
    `[:find ?ruid ?rdata :where
      [?p :block/uid "${pageUid}"]
      [?p :block/children ?c]
      [?c :block/uid ?ruid]
      [?c :block/props ?pr]
      [(get ?pr :${DISCOURSE_GRAPH_PROP_NAME}) ?rdata] ]`,
  );
  return r.map((x) => ({
    relationId: x[0] as string,
    ...(x[1] as ReifiedRelationData),
  }));
};

export const createReifiedRelation = async ({
  sourceUid,
  relationBlockUid,
  destinationUid,
  tentative,
}: {
  sourceUid: string;
  relationBlockUid: string;
  destinationUid: string;
  tentative?: boolean;
}): Promise<string> => {
  const parameterUids: Record<string, string> = {
    sourceUid,
    destinationUid,
    ...(tentative !== undefined && {
      [TENTATIVE_PROP_KEY]: String(tentative),
    }),
  };
  return await createReifiedBlock({
    destinationBlockUid: await getOrCreateRelationPageUid(),
    schemaUid: relationBlockUid,
    parameterUids,
  });
};

